@app.route("/vacas/nova", methods=["GET","POST"], defaults={"cadastro_vaca_url": True})
@app.route("/rebanho/novo", methods=["GET","POST"], defaults={"cadastro_vaca_url": False})
@login_required
def animal_novo(cadastro_vaca_url=False):
    if request.method=="POST":
        f=request.form
        brinco=f.get("brinco","").strip()
        if not brinco:
            flash("O brinco é obrigatório.","erro")
            return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=cadastro_vaca_url or request.args.get('voltar_para')=='vacas', matrizes_rows=obter_matrizes_cadastradas() if (cadastro_vaca_url or request.args.get('voltar_para')=='vacas') else [], filhos_rows=[], filho_editar=None)
        c=db()
        try:
            voltar_para=request.form.get("voltar_para","") or request.args.get("voltar_para","")
            cadastro_vaca = cadastro_vaca_url or voltar_para == "vacas"
            if cadastro_vaca:
                voltar_para = "vacas"
            if cadastro_vaca:
                existente = c.execute("""SELECT id FROM animais WHERE brinco=?
                                          AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha') LIMIT 1""", (brinco,)).fetchone()
            else:
                existente = c.execute("SELECT id FROM animais WHERE brinco=? LIMIT 1", (brinco,)).fetchone()
            if existente:
                flash("Esse brinco já está cadastrado para outra matriz." if cadastro_vaca else "Esse brinco já está cadastrado.","erro")
                return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=cadastro_vaca, matrizes_rows=obter_matrizes_cadastradas() if cadastro_vaca else [], filhos_rows=[], filho_editar=None)
            categoria = categoria_automatica("Fêmea", f.get("nascimento","")) if cadastro_vaca else f.get("categoria","")
            sexo = "Fêmea" if cadastro_vaca else f.get("sexo","Fêmea")
            origem_compra = (f.get("origem","") == "compra" or request.args.get("origem","") == "compra")
            origem = "Cadastro de Matrizes" if cadastro_vaca else ("Compra" if origem_compra else "Web")

            # V6.0.90 - inclusão opcional da cria no próprio cadastro da matriz.
            incluir_cria = cadastro_vaca and f.get("incluir_cria") == "1"
            nucleo_matriz = nucleo_idade(f.get("nascimento","")) if cadastro_vaca else ""
            cria_brinco = f.get("cria_brinco","").strip()
            cria_sexo = f.get("cria_sexo","Macho")
            cria_ano = f.get("cria_ano_safra") or str(date.today().year)
            cria_obs = f.get("cria_observacoes","")
            gemeos = incluir_cria and f.get("gemeos") == "1"
            cria2_brinco = f.get("cria2_brinco","").strip()
            cria2_sexo = f.get("cria2_sexo","Macho")
            cria2_ano = f.get("cria2_ano_safra") or str(date.today().year)
            cria2_obs = f.get("cria2_observacoes","")
            cria_registro_id = f.get("cria_registro_id", "").strip()
            # V6.1.01: ao editar um nascimento, permite corrigir a mãe/matriz.
            cria_mae_brinco = (f.get("cria_mae_brinco") or brinco).strip()
            if incluir_cria:
                if nucleo_matriz not in ("24-36 meses", "+36 meses"):
                    flash("A inclusão de nascimento só é liberada para matrizes dos núcleos 24-36 meses ou +36 meses.","erro")
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=[], filho_editar=None)
                if not cria_brinco:
                    flash("Informe o brinco da cria.","erro")
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=[], filho_editar=None)
                repetido = c.execute("SELECT id FROM nascimentos WHERE terneiro_brinco=? LIMIT 1", (cria_brinco,)).fetchone()
                animal_conflito = c.execute("""SELECT id FROM animais WHERE brinco=?
                    AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""", (cria_brinco,)).fetchone()
                if repetido or animal_conflito:
                    flash(f"O brinco da cria {cria_brinco} já está cadastrado e não pode ser repetido.","erro")
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=[], filho_editar=None)
                if gemeos:
                    if not cria2_brinco:
                        flash("Informe o brinco da segunda cria (gêmea).","erro")
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=[], filho_editar=None)
                    if cria2_brinco == cria_brinco:
                        flash("As duas crias gêmeas precisam ter brincos diferentes.","erro")
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=[], filho_editar=None)
                    repetido2 = c.execute("SELECT id FROM nascimentos WHERE terneiro_brinco=? LIMIT 1", (cria2_brinco,)).fetchone()
                    animal_conflito2 = c.execute("""SELECT id FROM animais WHERE brinco=?
                        AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""", (cria2_brinco,)).fetchone()
                    if repetido2 or animal_conflito2:
                        flash(f"O brinco da segunda cria {cria2_brinco} já está cadastrado e não pode ser repetido.","erro")
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=[], filho_editar=None)

            diu_aplicado = 1 if (cadastro_vaca and f.get("diu_aplicado") == "1") else 0
            c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,peso_atual,status,mae_brinco,pai_brinco,origem,observacoes,diu_aplicado)
                         VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                      (brinco,f.get("nome",""),sexo,f.get("raca",""),f.get("nascimento",""),
                       categoria,f.get("lote",""),float(f["peso_atual"]) if f.get("peso_atual") else None,
                       f.get("status","Ativo"),f.get("mae_brinco",""),f.get("pai_brinco",""),origem,f.get("observacoes",""),diu_aplicado))

            if incluir_cria:
                cria_cat = categoria_automatica(cria_sexo, cria_ano)
                c.execute("INSERT INTO nascimentos(terneiro_brinco,vaca_brinco,sexo,data_nascimento,observacoes) VALUES(?,?,?,?,?)",
                          (cria_brinco, brinco, cria_sexo, cria_ano, cria_obs))
                c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,status,mae_brinco,origem,observacoes)
                             VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                          (cria_brinco,"",cria_sexo,"",cria_ano,cria_cat,f.get("lote",""),"Ativo",brinco,"Nascimento Web",cria_obs))
                if gemeos:
                    cria2_cat = categoria_automatica(cria2_sexo, cria2_ano)
                    c.execute("INSERT INTO nascimentos(terneiro_brinco,vaca_brinco,sexo,data_nascimento,observacoes) VALUES(?,?,?,?,?)",
                              (cria2_brinco, brinco, cria2_sexo, cria2_ano, cria2_obs))
                    c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,status,mae_brinco,origem,observacoes)
                                 VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                              (cria2_brinco,"",cria2_sexo,"",cria2_ano,cria2_cat,f.get("lote",""),"Ativo",brinco,"Nascimento Web",cria2_obs))

            c.commit()
            flash("Matriz e duas crias gêmeas cadastradas." if incluir_cria and gemeos else ("Matriz e cria cadastradas." if incluir_cria else ("Matriz cadastrada." if cadastro_vaca else "Animal cadastrado.")),"ok")
            if voltar_para == "pesagens":
                return redirect(url_for("pesagens"))
            if voltar_para == "movimentacoes":
                return redirect(url_for("movimentacoes"))
            if voltar_para == "vacas":
                # V6.0.94: após salvar, volta para um formulário novo e limpo.
                return redirect("/vacas/nova")
            return redirect(url_for("rebanho"))
        except sqlite3.IntegrityError:
            flash("Esse brinco já está cadastrado.","erro")
        finally: c.close()
    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=None, modo_vaca=cadastro_vaca_url or request.args.get('voltar_para')=='vacas', matrizes_rows=obter_matrizes_cadastradas() if (cadastro_vaca_url or request.args.get('voltar_para')=='vacas') else [], filhos_rows=[], filho_editar=None)

@app.route("/rebanho/<int:id>/editar", methods=["GET","POST"])
@login_required
def animal_editar(id):
    c=db(); a=c.execute("SELECT * FROM animais WHERE id=?",(id,)).fetchone()
    if not a: c.close(); abort(404)
    editar_vaca_get = request.args.get('voltar_para') == 'vacas'
    filhos_rows = obter_nascimentos_matriz(a['brinco']) if editar_vaca_get else []
    filho_editar = None
    editar_filho_id = request.args.get('editar_filho', type=int)
    if editar_vaca_get and editar_filho_id:
        filho_editar = c.execute("SELECT * FROM nascimentos WHERE id=? AND vaca_brinco=?", (editar_filho_id, a['brinco'])).fetchone()
    if request.method=="POST":
        f=request.form
        brinco=f.get("brinco","").strip()
        if not brinco:
            flash("O brinco é obrigatório.","erro")
            c.close()
            return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=request.args.get('voltar_para')=='vacas', matrizes_rows=obter_matrizes_cadastradas() if request.args.get('voltar_para')=='vacas' else [], filhos_rows=filhos_rows, filho_editar=filho_editar)
        try:
            editar_vaca = request.form.get("voltar_para") == "vacas" or request.args.get("voltar_para") == "vacas"
            if editar_vaca:
                outra=c.execute("""SELECT id FROM animais WHERE brinco=? AND id<>?
                                    AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha') LIMIT 1""",(brinco,id)).fetchone()
                if outra:
                    flash("Esse brinco já está cadastrado para outra matriz.","erro")
                    c.close()
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
            categoria = categoria_automatica("Fêmea", f.get("nascimento","")) if editar_vaca else f.get("categoria","")
            sexo = "Fêmea" if editar_vaca else f.get("sexo","Fêmea")
            incluir_cria = editar_vaca and f.get("incluir_cria") == "1"
            nucleo_matriz = nucleo_idade(f.get("nascimento","")) if editar_vaca else ""
            cria_brinco = f.get("cria_brinco","").strip()
            cria_sexo = f.get("cria_sexo","Macho")
            cria_ano = f.get("cria_ano_safra") or str(date.today().year)
            cria_obs = f.get("cria_observacoes","")
            cria_registro_id = f.get("cria_registro_id", "").strip()
            gemeos = incluir_cria and not cria_registro_id and f.get("gemeos") == "1"
            cria2_brinco = f.get("cria2_brinco","").strip()
            cria2_sexo = f.get("cria2_sexo","Macho")
            cria2_ano = f.get("cria2_ano_safra") or str(date.today().year)
            cria2_obs = f.get("cria2_observacoes","")
            # V6.1.01: ao editar um nascimento, permite corrigir a mãe/matriz.
            cria_mae_brinco = (f.get("cria_mae_brinco") or brinco).strip()
            if incluir_cria:
                if nucleo_matriz not in ("24-36 meses", "+36 meses"):
                    flash("A inclusão de nascimento só é liberada para matrizes dos núcleos 24-36 meses ou +36 meses.","erro")
                    c.close()
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
                if not cria_brinco:
                    flash("Informe o brinco da cria.","erro")
                    c.close()
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
                if cria_registro_id:
                    mae_destino = c.execute("""SELECT brinco,lote FROM animais WHERE brinco=?
                        AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha') LIMIT 1""", (cria_mae_brinco,)).fetchone()
                    if not mae_destino:
                        flash("Selecione uma mãe/matriz cadastrada para este nascimento.","erro")
                        c.close()
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
                    repetido=c.execute("SELECT id FROM nascimentos WHERE terneiro_brinco=? AND id<>? LIMIT 1",(cria_brinco,cria_registro_id)).fetchone()
                    nasc_atual=c.execute("SELECT terneiro_brinco FROM nascimentos WHERE id=? AND vaca_brinco=?",(cria_registro_id,a['brinco'])).fetchone()
                    brinco_cria_atual=nasc_atual['terneiro_brinco'] if nasc_atual else None
                    animal_conflito=c.execute("""SELECT id FROM animais WHERE brinco=?
                        AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web'
                        AND (? IS NULL OR brinco<>?) LIMIT 1""",(cria_brinco,brinco_cria_atual,brinco_cria_atual)).fetchone()
                else:
                    repetido=c.execute("SELECT id FROM nascimentos WHERE terneiro_brinco=? LIMIT 1",(cria_brinco,)).fetchone()
                    animal_conflito=c.execute("""SELECT id FROM animais WHERE brinco=?
                        AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""",(cria_brinco,)).fetchone()
                if repetido or animal_conflito:
                    flash(f"O brinco da cria {cria_brinco} já está cadastrado e não pode ser repetido.","erro")
                    c.close()
                    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
                if gemeos:
                    if not cria2_brinco:
                        flash("Informe o brinco da segunda cria (gêmea).","erro")
                        c.close()
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
                    if cria2_brinco == cria_brinco:
                        flash("As duas crias gêmeas precisam ter brincos diferentes.","erro")
                        c.close()
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)
                    repetido2=c.execute("SELECT id FROM nascimentos WHERE terneiro_brinco=? LIMIT 1",(cria2_brinco,)).fetchone()
                    animal_conflito2=c.execute("""SELECT id FROM animais WHERE brinco=?
                        AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""",(cria2_brinco,)).fetchone()
                    if repetido2 or animal_conflito2:
                        flash(f"O brinco da segunda cria {cria2_brinco} já está cadastrado e não pode ser repetido.","erro")
                        c.close()
                        return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=f, modo_vaca=True, matrizes_rows=obter_matrizes_cadastradas(), filhos_rows=filhos_rows, filho_editar=filho_editar)

            # V6.1.02: peso e estado/status não pertencem ao cadastro do animal.
            # Ao editar, preserva esses valores (peso vem de Pesagens; status é controlado pelos fluxos próprios).
            diu_aplicado = 1 if (editar_vaca and f.get("diu_aplicado") == "1") else (int(a["diu_aplicado"] or 0) if "diu_aplicado" in a.keys() else 0)
            c.execute("""UPDATE animais SET brinco=?,nome=?,sexo=?,raca=?,nascimento=?,categoria=?,lote=?,
                         mae_brinco=?,pai_brinco=?,observacoes=?,diu_aplicado=? WHERE id=?""",
                      (brinco,f.get("nome",""),sexo,f.get("raca",""),
                       f.get("nascimento",""),categoria,f.get("lote",""),
                       f.get("mae_brinco",""),f.get("pai_brinco",""),f.get("observacoes",""),diu_aplicado,id))
            # V6.1.56: DIU retira a matriz de toda reprodução ativa, preservando o histórico.
            if editar_vaca and diu_aplicado == 1:
                # Encerra IATF ativa sem apagar D0/D8/D10/IA já registrados.
                regs_iatf = c.execute("""SELECT id,observacoes FROM inseminacoes
                                         WHERE matriz_brinco=?
                                           AND LOWER(TRIM(COALESCE(resultado,''))) NOT IN ('vazia','cancelado')""",
                                      (a['brinco'],)).fetchall()
                for reg_iatf in regs_iatf:
                    obs_ant=(reg_iatf['observacoes'] or '').strip()
                    nota='IATF encerrada automaticamente por DIU APLICADO.'
                    obs_nova=(obs_ant + ('\n' if obs_ant else '') + nota).strip()
                    c.execute("UPDATE inseminacoes SET resultado='Cancelado', observacoes=? WHERE id=?",
                              (obs_nova,reg_iatf['id']))
                # Também retira do TOURO, se houver registro ativo.
                c.execute("UPDATE entouramentos SET ativo=0 WHERE matriz_brinco=? AND COALESCE(ativo,1)=1",
                          (a['brinco'],))

            if editar_vaca and brinco != a['brinco']:
                c.execute("UPDATE nascimentos SET vaca_brinco=? WHERE vaca_brinco=?", (brinco, a['brinco']))
                c.execute("""UPDATE animais SET mae_brinco=? WHERE mae_brinco=?
                             AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web'""", (brinco, a['brinco']))
            if incluir_cria:
                cria_cat = categoria_automatica(cria_sexo, cria_ano)
                if cria_registro_id:
                    nasc_atual=c.execute("SELECT * FROM nascimentos WHERE id=? AND vaca_brinco=?",(cria_registro_id,a['brinco'])).fetchone()
                    if nasc_atual:
                        brinco_antigo=nasc_atual['terneiro_brinco']
                        mae_final = cria_mae_brinco or brinco
                        if brinco != a['brinco'] and mae_final == a['brinco']:
                            mae_final = brinco
                        mae_destino = c.execute("""SELECT brinco,lote FROM animais WHERE brinco=?
                            AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha') LIMIT 1""", (mae_final,)).fetchone()
                        lote_cria = ((mae_destino['lote'] if mae_destino else '') or '')
                        c.execute("UPDATE nascimentos SET terneiro_brinco=?,vaca_brinco=?,sexo=?,data_nascimento=?,observacoes=? WHERE id=?",
                                  (cria_brinco,mae_final,cria_sexo,cria_ano,cria_obs,cria_registro_id))
                        ar=c.execute("""SELECT id FROM animais WHERE brinco=? AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""",(brinco_antigo,)).fetchone()
                        if ar:
                            c.execute("""UPDATE animais SET brinco=?,sexo=?,nascimento=?,categoria=?,lote=?,mae_brinco=?,observacoes=? WHERE id=?""",
                                      (cria_brinco,cria_sexo,cria_ano,cria_cat,lote_cria,mae_final,cria_obs,ar['id']))
                    else:
                        cria_registro_id=''
                if not cria_registro_id:
                    c.execute("INSERT INTO nascimentos(terneiro_brinco,vaca_brinco,sexo,data_nascimento,observacoes) VALUES(?,?,?,?,?)",
                              (cria_brinco, brinco, cria_sexo, cria_ano, cria_obs))
                    c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,status,mae_brinco,origem,observacoes)
                                 VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                              (cria_brinco,"",cria_sexo,"",cria_ano,cria_cat,f.get("lote",""),"Ativo",brinco,"Nascimento Web",cria_obs))
                    if gemeos:
                        cria2_cat = categoria_automatica(cria2_sexo, cria2_ano)
                        c.execute("INSERT INTO nascimentos(terneiro_brinco,vaca_brinco,sexo,data_nascimento,observacoes) VALUES(?,?,?,?,?)",
                                  (cria2_brinco, brinco, cria2_sexo, cria2_ano, cria2_obs))
                        c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,status,mae_brinco,origem,observacoes)
                                     VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                                  (cria2_brinco,"",cria2_sexo,"",cria2_ano,cria2_cat,f.get("lote",""),"Ativo",brinco,"Nascimento Web",cria2_obs))
            c.commit(); c.close(); flash("Cadastro atualizado e gêmeos incluídos." if incluir_cria and gemeos else ("Cadastro atualizado e nascimento atualizado." if incluir_cria and cria_registro_id else ("Cadastro atualizado e nascimento incluído." if incluir_cria else "Cadastro atualizado.")),"ok")
            if request.form.get("voltar_para") == "vacas":
                # V6.0.94: encerra a edição e prepara uma nova inclusão limpa.
                return redirect("/vacas/nova")
            return redirect(url_for("rebanho"))
        except sqlite3.IntegrityError:
            flash("Esse brinco já está em uso.","erro")
    c.close()
    return render_template('animal_form.html', campos_lotes=get_campos_lotes(), a=a, modo_vaca=request.args.get('voltar_para')=='vacas', matrizes_rows=obter_matrizes_cadastradas() if request.args.get('voltar_para')=='vacas' else [], filhos_rows=filhos_rows, filho_editar=filho_editar)

@app.route("/matrizes/<int:matriz_id>/nascimentos/<int:nascimento_id>/excluir", methods=["POST"])
@login_required
def excluir_nascimento_matriz(matriz_id, nascimento_id):
    c=db()
    try:
        matriz=c.execute("SELECT id,brinco FROM animais WHERE id=?", (matriz_id,)).fetchone()
        if not matriz:
            abort(404)
        nasc=c.execute("SELECT * FROM nascimentos WHERE id=? AND vaca_brinco=?", (nascimento_id, matriz['brinco'])).fetchone()
        if not nasc:
            abort(404)
        brinco_cria=nasc['terneiro_brinco']
        c.execute("DELETE FROM nascimentos WHERE id=?", (nascimento_id,))
        c.execute("""DELETE FROM animais WHERE brinco=?
                     AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web'""", (brinco_cria,))
        c.commit()
        return ('', 204)
    finally:
        c.close()

@app.route("/nascimentos", methods=["GET","POST"])
@login_required
def nascimentos():
    c=db()
    if request.method=="POST":
        f=request.form
        b=f.get("terneiro_brinco","").strip()
        v=f.get("vaca_brinco","").strip()
        registro_id=f.get("registro_id","").strip()
        sexo=f.get("sexo","Macho")
        ano=f.get("ano_safra") or str(date.today().year)
        obs=f.get("observacoes","")

        if not b or not v:
            flash("Informe o brinco do terneiro e a vaca.","erro")
        else:
            atual=None
            if registro_id:
                atual=c.execute("SELECT * FROM nascimentos WHERE id=?",(registro_id,)).fetchone()
                if not atual:
                    flash("Registro de nascimento não encontrado.","erro")
                    c.close()
                    return redirect(url_for("nascimentos"))

            # O brinco do terneiro é único. A mesma vaca, porém, pode aparecer
            # em mais de um nascimento (inclusive gêmeos).
            if atual:
                repetido=c.execute(
                    "SELECT id FROM nascimentos WHERE terneiro_brinco=? AND id<>? LIMIT 1",
                    (b, atual["id"])
                ).fetchone()
                animal_conflito=c.execute(
                    """SELECT id,brinco FROM animais WHERE brinco=? AND brinco<>?
                       AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""",
                    (b, atual["terneiro_brinco"])
                ).fetchone()
            else:
                repetido=c.execute(
                    "SELECT id FROM nascimentos WHERE terneiro_brinco=? LIMIT 1",(b,)
                ).fetchone()
                animal_conflito=c.execute(
                    """SELECT id,brinco FROM animais WHERE brinco=?
                       AND LOWER(TRIM(COALESCE(origem,'')))='nascimento web' LIMIT 1""",(b,)
                ).fetchone()

            if repetido or animal_conflito:
                flash(f"O brinco do terneiro {b} já está cadastrado e não pode ser repetido.","erro")
            else:
                cat=categoria_automatica(sexo, ano)
                lote_mae=c.execute("""SELECT lote FROM animais WHERE brinco=? AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha') LIMIT 1""",(v,)).fetchone()
                lote=(lote_mae["lote"] if lote_mae else "") or ""

                if atual:
                    brinco_antigo=atual["terneiro_brinco"]
                    c.execute(
                        "UPDATE nascimentos SET terneiro_brinco=?,vaca_brinco=?,sexo=?,data_nascimento=?,observacoes=? WHERE id=?",
                        (b,v,sexo,ano,obs,atual["id"])
                    )
                    ar=c.execute("""SELECT id FROM animais WHERE brinco=? AND LOWER(TRIM(COALESCE(origem,''))) = 'nascimento web' LIMIT 1""",(brinco_antigo,)).fetchone()
                    if ar:
                        c.execute(
                            """UPDATE animais SET brinco=?,sexo=?,nascimento=?,categoria=?,mae_brinco=?,lote=?,observacoes=? WHERE id=?""",
                            (b,sexo,ano,cat,v,lote,obs,ar["id"])
                        )
                    else:
                        c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,status,mae_brinco,origem,observacoes)
                                     VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                                  (b,"",sexo,"",ano,cat,lote,"Ativo",v,"Nascimento Web",obs))
                    c.commit()
                    c.close()
                    flash("Nascimento atualizado.","ok")
                    return redirect(url_for("nascimentos"))
                else:
                    c.execute(
                        "INSERT INTO nascimentos(terneiro_brinco,vaca_brinco,sexo,data_nascimento,observacoes) VALUES(?,?,?,?,?)",
                        (b,v,sexo,ano,obs)
                    )
                    c.execute("""INSERT INTO animais(brinco,nome,sexo,raca,nascimento,categoria,lote,status,mae_brinco,origem,observacoes)
                                 VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                              (b,"",sexo,"",ano,cat,lote,"Ativo",v,"Nascimento Web",obs))
                    c.commit()
                    c.close()
                    flash("Nascimento salvo.","ok")
                    return redirect(url_for("nascimentos"))

    candidatas_nascimento = c.execute("""
        SELECT *
        FROM animais
        WHERE status='Ativo'
          AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha')
        ORDER BY
          CASE WHEN brinco GLOB '[0-9]*' THEN CAST(brinco AS INTEGER) ELSE 999999999 END,
          brinco COLLATE NOCASE
    """).fetchall()
    # V6.1.06: na tela geral de nascimentos, todas as matrizes ativas ficam disponíveis
    # para permitir corrigir a mãe de um nascimento lançado incorretamente.
    vacas = list(candidatas_nascimento)

    editar=None
    editar_id=request.args.get("editar","").strip()
    if editar_id:
        editar=c.execute("SELECT * FROM nascimentos WHERE id=?",(editar_id,)).fetchone()
        if not editar:
            flash("Registro de nascimento não encontrado.","erro")

    rows=c.execute("""
        SELECT * FROM nascimentos
        ORDER BY
          CASE WHEN terneiro_brinco GLOB '[0-9]*' THEN 0 ELSE 1 END,
          CASE WHEN terneiro_brinco GLOB '[0-9]*' THEN CAST(terneiro_brinco AS INTEGER) ELSE NULL END,
          terneiro_brinco COLLATE NOCASE,
          id
    """).fetchall()
    c.close()
    return render_template("nascimentos.html", rows=rows, vacas=vacas, editar=editar)

@app.route("/campos", methods=["GET","POST"])
@login_required
def campos():
    c=db()
    if request.method=="POST":
        f=request.form
        try:
            c.execute("""INSERT INTO campos(nome,area_ha,pastagem,capacidade,situacao,observacoes) VALUES(?,?,?,?,?,?)""",
                      (f.get("nome","").strip(), float(f["area_ha"]) if f.get("area_ha") else None, f.get("pastagem",""),
                       float(f["capacidade"]) if f.get("capacidade") else None, f.get("situacao","Em uso"),f.get("observacoes","")))
            c.commit(); flash("Campo cadastrado.","ok")
            c.close()
            return redirect(url_for("campos"))
        except sqlite3.IntegrityError: flash("Já existe um campo com esse nome.","erro")
    rows=c.execute("""SELECT c.*, (SELECT COUNT(*) FROM animais a WHERE a.status='Ativo' AND a.lote=c.nome) ocupacao
                      FROM campos c ORDER BY c.nome""").fetchall()
    c.close()
    return render_template("campos.html",rows=rows)

@app.route("/pesagens", methods=["GET","POST"])
@login_required
def pesagens():
    c=db()
    # Compatibilidade direta com bancos antigos: a própria tela garante
    # os campos usados pela versão atual antes de consultar os registros.
    pes_cols={r["name"] for r in c.execute("PRAGMA table_info(pesagens)").fetchall()}
    if "nome_avulso" not in pes_cols:
        c.execute("ALTER TABLE pesagens ADD COLUMN nome_avulso TEXT")
    if "avulso" not in pes_cols:
        c.execute("ALTER TABLE pesagens ADD COLUMN avulso INTEGER NOT NULL DEFAULT 0")
    c.execute("UPDATE pesagens SET avulso=0 WHERE avulso IS NULL")
    c.commit()
    if request.method=="POST":
        acao=request.form.get("acao","salvar")
        if acao=="excluir":
            ids=request.form.getlist("pesagem_id")
            if ids:
                marks=",".join("?" for _ in ids)
                c.execute(f"DELETE FROM pesagens WHERE id IN ({marks})", ids)
                c.commit(); flash("Pesagem(ns) excluída(s).","ok")
            else:
                flash("Selecione ao menos uma pesagem para excluir.","erro")
        else:
            f=request.form
            avulso=f.get("modo_pesagem")=="avulso"
            b=((f.get("brinco_avulso") if avulso else f.get("brinco")) or "").strip()
            nome_avulso=f.get("nome_avulso","").strip() if avulso else ""
            try:
                p=float(f.get("peso") or 0)
                if not b or p<=0: raise ValueError
                lote="" if avulso else f.get("lote","").strip()
                if not avulso and not lote:
                    ar=c.execute("SELECT lote FROM animais WHERE brinco=? AND status='Ativo'",(b,)).fetchone()
                    lote=(ar["lote"] if ar else "") or ""
                c.execute("INSERT INTO pesagens(brinco,nome_avulso,avulso,data,peso,lote,observacoes) VALUES(?,?,?,?,?,?,?)",
                          (b,nome_avulso,1 if avulso else 0,f.get("data") or date.today().isoformat(),p,lote,f.get("observacoes","")))
                if not avulso: c.execute("UPDATE animais SET peso_atual=? WHERE brinco=?",(p,b))
                c.commit(); flash("Pesagem avulsa salva. O animal não foi incluído no Rebanho." if avulso else "Pesagem salva.","ok")
                c.close()
                return redirect(url_for("pesagens"))
            except ValueError: flash("Informe a identificação e um peso válido.","erro")
    animais=c.execute("""SELECT brinco,nome,lote FROM animais
                         WHERE status='Ativo'
                         ORDER BY CASE WHEN TRIM(COALESCE(brinco,'')) GLOB '[0-9]*'
                                       THEN CAST(brinco AS INTEGER) ELSE 999999999 END,
                                  brinco COLLATE NOCASE""").fetchall()
    raw=c.execute("""SELECT * FROM pesagens
                     ORDER BY COALESCE(brinco,''), COALESCE(data,''), COALESCE(id,rowid)""").fetchall()
    prev={}; calc=[]
    for r in raw:
        item=dict(r); br=str(r['brinco'] or ''); chave=('AVULSO:' if r['avulso'] else 'REBANHO:')+br; ant=prev.get(chave)
        item['ganho']=None; item['dias']=None; item['gmd']=None
        if ant:
            try:
                d1=datetime.strptime(ant['data'],'%Y-%m-%d').date(); d2=datetime.strptime(r['data'],'%Y-%m-%d').date()
                dias=(d2-d1).days; ganho=round(float(r['peso'])-float(ant['peso']),1)
                item['ganho']=ganho; item['dias']=dias; item['gmd']=round(ganho/dias,3) if dias>0 else None
            except Exception: pass
        prev[chave]=r
        calc.append(item)
    rows=list(reversed(calc))[:150]
    c.close()
    return render_template("pesagens.html",animais=animais,rows=rows,campos_lotes=get_campos_lotes())

@app.route("/medicacoes", methods=["GET","POST"])
@login_required
def medicacoes():
    c=db()
    if request.method=="POST":
        f=request.form
        acao=f.get("acao","aplicar")

        if acao=="cadastrar_medicacao":
            nome=f.get("nome","").strip()
            if not nome:
                flash("Informe o nome da medicação.","erro")
            else:
                try:
                    valor_produto = parse_money(f.get("valor_produto", ""))
                    quantidade_embalagem = parse_money(f.get("quantidade_embalagem", ""))
                    dose_num = parse_money(f.get("dose_padrao", ""))
                    custo_animal = 0.0
                    if valor_produto > 0 and quantidade_embalagem > 0 and dose_num > 0:
                        custo_animal = round((valor_produto / quantidade_embalagem) * dose_num, 2)
                    c.execute("""INSERT INTO medicamentos(nome,tipo,dose_padrao,unidade,fabricante,valor_produto,quantidade_embalagem,custo_animal,observacoes)
                                 VALUES(?,?,?,?,?,?,?,?,?)""",
                              (nome,f.get("tipo","").strip(),f.get("dose_padrao","").strip(),
                               f.get("unidade","").strip(),f.get("fabricante","").strip(),
                               valor_produto,quantidade_embalagem,custo_animal,f.get("observacoes","").strip()))
                    c.commit()
                    flash("Medicação cadastrada.","ok")
                    c.close()
                    return redirect(url_for("medicacoes"))
                except sqlite3.IntegrityError:
                    flash("Já existe uma medicação com esse nome.","erro")

        elif acao=="excluir_medicacao":
            mid=f.get("medicamento_id","").strip()
            if mid:
                c.execute("UPDATE medicamentos SET ativo=0 WHERE id=?",(mid,))
                c.commit()
                flash("Medicação removida da lista ativa.","ok")

        elif acao=="aplicar":
            mid=f.get("medicamento_id","").strip()
            data_aplicacao=f.get("data") or date.today().isoformat()
            proxima_data=f.get("proxima_data","")
            obs=f.get("observacoes","").strip()
            dose_informada=f.get("dose","").strip()
            modo=f.get("modo_aplicacao","individual")

            med=c.execute("SELECT * FROM medicamentos WHERE id=? AND ativo=1",(mid,)).fetchone() if mid else None
            if not med:
                flash("Selecione uma medicação cadastrada.","erro")
            else:
                dose=dose_informada or (med["dose_padrao"] or "")
                tipo=med["tipo"] or "Medicação"
                produto=med["nome"]

                if modo=="individual":
                    brincos=[b for b in f.getlist("brincos") if b]
                    if not brincos:
                        flash("Selecione ao menos um animal.","erro")
                        brincos=[]
                    alvos=[]
                    if brincos:
                        marks=",".join("?" for _ in brincos)
                        alvos=c.execute(f"""SELECT brinco,lote FROM animais
                                           WHERE status='Ativo' AND brinco IN ({marks})
                                           ORDER BY CAST(brinco AS INTEGER),brinco""", brincos).fetchall()
                elif modo=="campo":
                    campo=f.get("campo","").strip()
                    alvos=c.execute("""SELECT brinco,lote FROM animais
                                      WHERE status='Ativo' AND lote=?
                                      ORDER BY CAST(brinco AS INTEGER),brinco""",(campo,)).fetchall() if campo else []
                    if not campo:
                        flash("Selecione um Campo.","erro")
                elif modo=="categoria":
                    categoria=f.get("categoria","").strip()
                    alvos=c.execute("""SELECT brinco,lote FROM animais
                                      WHERE status='Ativo' AND categoria=?
                                      ORDER BY CAST(brinco AS INTEGER),brinco""",(categoria,)).fetchall() if categoria else []
                    if not categoria:
                        flash("Selecione uma Categoria.","erro")
                else:
                    alvos=c.execute("""SELECT brinco,lote FROM animais
                                      WHERE status='Ativo'
                                      ORDER BY CAST(brinco AS INTEGER),brinco""").fetchall()

                if 'alvos' in locals() and alvos:
                    for a in alvos:
                        c.execute("""INSERT INTO sanidade(brinco,lote,data,tipo,produto,dose,proxima_data,observacoes,custo_animal)
                                     VALUES(?,?,?,?,?,?,?,?,?)""",
                                  (a["brinco"],a["lote"] or "",data_aplicacao,tipo,produto,dose,proxima_data,obs,med["custo_animal"] or 0))
                    c.commit()
                    flash(f"Aplicação registrada para {len(alvos)} animal(is).","ok")
                    c.close()
                    return redirect(url_for("medicacoes"))
                elif 'alvos' in locals() and modo in ("campo","categoria","todos"):
                    flash("Nenhum animal ativo encontrado para a seleção.","erro")

    animais=c.execute("""SELECT brinco,nome,lote,categoria FROM animais
                         WHERE status='Ativo'
                         ORDER BY CAST(brinco AS INTEGER),brinco""").fetchall()
    medicamentos=c.execute("""SELECT * FROM medicamentos WHERE ativo=1
                              ORDER BY nome COLLATE NOCASE""").fetchall()
    categorias=c.execute("""SELECT DISTINCT categoria FROM animais
                            WHERE status='Ativo' AND TRIM(COALESCE(categoria,''))<>''
                            ORDER BY categoria COLLATE NOCASE""").fetchall()
    rows=c.execute("SELECT * FROM sanidade ORDER BY data DESC,id DESC LIMIT 150").fetchall()
    campos_lotes=get_campos_lotes()
    c.close()
    return render_template("medicacoes.html",animais=animais,medicamentos=medicamentos,
                           categorias=categorias,campos_lotes=campos_lotes,rows=rows)

@app.route("/iatf", methods=["GET","POST"])
@login_required
def iatf():
    c=db()
    # Garante a estrutura de IATF mesmo quando o banco veio de uma versão
    # anterior que ainda não possuía cadastro de protocolos.
    c.execute("""CREATE TABLE IF NOT EXISTS protocolos_iatf (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nome TEXT NOT NULL UNIQUE, etapa_d0 TEXT, dias_etapa2 INTEGER,
        etapa2 TEXT, dias_retirada INTEGER, retirada TEXT, dias_ia INTEGER,
        etapa_ia TEXT,
        observacoes TEXT, ativo INTEGER NOT NULL DEFAULT 1,
        criado_em TEXT DEFAULT CURRENT_TIMESTAMP
    )""")
    # V6.1.29 — reprodução por monta natural (touro).
    c.execute("""CREATE TABLE IF NOT EXISTS entouramentos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        matriz_brinco TEXT NOT NULL,
        data_entouramento TEXT NOT NULL,
        observacoes TEXT,
        ativo INTEGER NOT NULL DEFAULT 1,
        criado_em TEXT DEFAULT CURRENT_TIMESTAMP
    )""")
    ent_cols={r["name"] for r in c.execute("PRAGMA table_info(entouramentos)").fetchall()}
    if "ativo" not in ent_cols:
        c.execute("ALTER TABLE entouramentos ADD COLUMN ativo INTEGER NOT NULL DEFAULT 1")
    if "diagnostico_data" not in ent_cols:
        c.execute("ALTER TABLE entouramentos ADD COLUMN diagnostico_data TEXT")
    if "resultado" not in ent_cols:
        c.execute("ALTER TABLE entouramentos ADD COLUMN resultado TEXT")
    c.execute("UPDATE entouramentos SET ativo=1 WHERE ativo IS NULL")
    iatf_cols={r["name"] for r in c.execute("PRAGMA table_info(inseminacoes)").fetchall()}
    iatf_necessarias=[
        ("protocolo","TEXT"),("data_inicio","TEXT"),("etapa_d0","TEXT"),
        ("data_etapa2","TEXT"),("etapa2","TEXT"),("data_retirada","TEXT"),
        ("retirada","TEXT"),("data_ia","TEXT"),("etapa_ia","TEXT"),("hora_ia","TEXT"),
        ("semen_touro","TEXT"),("inseminador","TEXT"),("gnrh_aplicado","INTEGER NOT NULL DEFAULT 0"),("diagnostico_data","TEXT"),
        ("resultado","TEXT"),("observacoes","TEXT")
    ]
    for nome_coluna,tipo_coluna in iatf_necessarias:
        if nome_coluna not in iatf_cols:
            c.execute(f"ALTER TABLE inseminacoes ADD COLUMN {nome_coluna} {tipo_coluna}")
    c.commit()
    if request.method=="POST":
        f=request.form
        acao=f.get("acao","")

        if acao=="iniciar_reproducao":
            selecionados=[]
            for b in f.getlist("matrizes"):
                b=str(b or "").strip()
                if b and b not in selecionados: selecionados.append(b)
            if not selecionados:
                flash("Selecione ao menos uma matriz.","erro")
            else:
                inicio_iatf=f.get("data_inicio","").strip() or date.today().isoformat()
                data_touro=f.get("data_entouramento","").strip() or date.today().isoformat()
                pid=f.get("protocolo_id","").strip()
                protocolo=c.execute("SELECT * FROM protocolos_iatf WHERE id=? AND ativo=1",(pid,)).fetchone() if pid else None
                iatf=[]; touro=[]; sem_metodo=[]; bloqueados=[]
                for b in selecionados:
                    metodo=(f.get("metodo_"+b,"") or "").strip().upper()
                    if metodo not in ("IATF","TOURO"):
                        sem_metodo.append(b); continue
                    animal=c.execute("""SELECT id,categoria,nascimento FROM animais WHERE brinco=? AND status='Ativo'
                        AND COALESCE(diu_aplicado,0)=0 AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha')
                        ORDER BY id DESC LIMIT 1""",(b,)).fetchone()
                    apta=bool(animal and ((animal["categoria"] or "").strip().lower()=="vaca" or nucleo_idade(animal["nascimento"])=="24-36 meses"))
                    if not apta:
                        bloqueados.append(b)
                    elif metodo=="IATF":
                        # A escolha IATF na linha passa a ser a decisão atual da matriz.
                        # Se havia TOURO ativo, encerra-o antes de iniciar o protocolo.
                        c.execute("UPDATE entouramentos SET ativo=0 WHERE matriz_brinco=? AND COALESCE(ativo,1)=1",(b,))
                        # Não duplica uma IATF já ativa: ela continua na seção de andamento.
                        ult=c.execute("SELECT id,resultado FROM inseminacoes WHERE matriz_brinco=? ORDER BY id DESC LIMIT 1",(b,)).fetchone()
                        iatf_ativa=bool(ult and (ult["resultado"] or "").strip().lower() not in ("prenhe","vazia","cancelado"))
                        if iatf_ativa:
                            bloqueados.append(b)
                        else:
                            iatf.append(b)
                    else:
                        # A escolha TOURO encerra eventual IATF ativa e mantém somente
                        # um registro de entouramento ativo para a matriz.
                        ult=c.execute("SELECT id,resultado,observacoes FROM inseminacoes WHERE matriz_brinco=? ORDER BY id DESC LIMIT 1",(b,)).fetchone()
                        if ult and (ult["resultado"] or "").strip().lower() not in ("prenhe","vazia","cancelado"):
                            obs=(ult["observacoes"] or "").strip()
                            nota="IATF cancelada para troca de método reprodutivo."
                            obs=(obs+("\n" if obs else "")+nota).strip() if nota not in obs else obs
                            c.execute("UPDATE inseminacoes SET resultado='Cancelado',observacoes=? WHERE id=?",(obs,ult["id"]))
                        ja_touro=c.execute("SELECT 1 FROM entouramentos WHERE matriz_brinco=? AND COALESCE(ativo,1)=1 LIMIT 1",(b,)).fetchone()
                        if ja_touro:
                            bloqueados.append(b)
                        else:
                            touro.append(b)
                if iatf and not protocolo:
                    flash("Selecione o protocolo cadastrado para as matrizes marcadas como IATF.","erro")
                else:
                    def somar_data(txt,dias):
                        if not txt or dias is None: return ""
                        try: return (datetime.strptime(txt,"%Y-%m-%d").date()+timedelta(days=int(dias))).isoformat()
                        except: return ""
                    if protocolo:
                        d2=somar_data(inicio_iatf,protocolo["dias_etapa2"]); dr=somar_data(inicio_iatf,protocolo["dias_retirada"]); dia=somar_data(inicio_iatf,protocolo["dias_ia"])
                        for b in iatf:
                            c.execute("""INSERT INTO inseminacoes (matriz_brinco,protocolo,data_inicio,etapa_d0,data_etapa2,etapa2,data_retirada,retirada,data_ia,etapa_ia,hora_ia,semen_touro,inseminador,diagnostico_data,resultado,observacoes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                                (b,protocolo["nome"],inicio_iatf,protocolo["etapa_d0"] or "",d2,protocolo["etapa2"] or "",dr,protocolo["retirada"] or "",dia,protocolo["etapa_ia"] or "","","","","","",protocolo["observacoes"] or ""))
                    for b in touro:
                        c.execute("INSERT INTO entouramentos(matriz_brinco,data_entouramento,observacoes) VALUES(?,?,?)",(b,data_touro,""))
                    c.commit()
                    if iatf: flash(f"Protocolo IATF aplicado em {len(iatf)} matriz(es).","ok")
                    if touro: flash(f"Entouramento registrado para {len(touro)} matriz(es).","ok")
                    if sem_metodo: flash("Escolha IATF ou TOURO para: "+", ".join(sem_metodo),"erro")
                    if bloqueados: flash("Matriz(es) indisponível(is): "+", ".join(bloqueados),"erro")
                    if iatf or touro:
                        c.close(); return redirect(url_for("iatf"))

        elif acao=="registrar_entouramento":
            brincos=[]
            for b in (f.getlist("matrizes_touro") or f.getlist("matrizes")):
                b=str(b or "").strip()
                if b and b not in brincos:
                    brincos.append(b)
            data_entouramento=f.get("data_entouramento","").strip() or date.today().isoformat()
            obs=f.get("observacoes_entouramento","").strip()
            if not brincos:
                flash("Selecione ao menos uma vaca para o entouramento.","erro")
            else:
                validos=[]
                bloqueados_iatf=[]
                for b in brincos:
                    animal_ok=c.execute("""SELECT categoria,nascimento FROM animais WHERE brinco=? AND status='Ativo'
                                    AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha')
                                    AND COALESCE(diu_aplicado,0)=0 LIMIT 1""",(b,)).fetchone()
                    ok=bool(animal_ok and ((animal_ok["categoria"] or "").strip().lower()=="vaca" or nucleo_idade(animal_ok["nascimento"])=="24-36 meses"))
                    ult_iatf=c.execute("""SELECT resultado FROM inseminacoes WHERE matriz_brinco=?
                                           ORDER BY id DESC LIMIT 1""",(b,)).fetchone()
                    iatf_ativa=bool(ult_iatf and (ult_iatf['resultado'] or '').strip().lower() not in ('vazia','cancelado'))
                    ja_no_touro=c.execute("""SELECT 1 FROM entouramentos
                                                WHERE matriz_brinco=? AND COALESCE(ativo,1)=1 LIMIT 1""",(b,)).fetchone()
                    if ok and not iatf_ativa and not ja_no_touro:
                        validos.append(b)
                    elif ok and iatf_ativa:
                        bloqueados_iatf.append(b)
                for b in validos:
                    c.execute("""INSERT INTO entouramentos(matriz_brinco,data_entouramento,observacoes)
                                 VALUES(?,?,?)""",(b,data_entouramento,obs))
                c.commit()
                if bloqueados_iatf:
                    flash("Não incluída(s) no entouramento porque já estão em IATF: "+", ".join(bloqueados_iatf), "erro")
                if validos:
                    flash(f"Entouramento registrado para {len(validos)} vaca(s).","ok")
                    c.close()
                    return redirect(url_for("iatf"))
                flash("Nenhuma vaca disponível foi selecionada.","erro")

        elif acao=="excluir_entouramento":
            eid=f.get("entouramento_id","").strip()
            if eid:
                reg=c.execute("SELECT matriz_brinco FROM entouramentos WHERE id=?",(eid,)).fetchone()
                if reg:
                    c.execute("UPDATE entouramentos SET ativo=0 WHERE matriz_brinco=? AND COALESCE(ativo,1)=1",(reg["matriz_brinco"],))
                    c.commit(); flash(f"Matriz {reg['matriz_brinco']} retirada do TOURO.","ok")
                c.close(); return redirect(url_for("iatf"))

        elif acao=="diagnostico_touro":
            eid=f.get("entouramento_id","").strip()
            resultado=f.get("resultado","").strip()
            data_diag=f.get("diagnostico_data","").strip() or date.today().isoformat()
            if resultado not in ("Prenhe","Vazia"):
                flash("Informe o resultado do diagnóstico: Prenhe ou Vazia.","erro")
            elif eid:
                reg=c.execute("SELECT matriz_brinco,observacoes FROM entouramentos WHERE id=?",(eid,)).fetchone()
                if reg:
                    obs=(reg["observacoes"] or "").strip()
                    nota=f"Diagnóstico {resultado} em {data_diag}."
                    obs_final=(obs+"\n"+nota).strip() if obs else nota
                    c.execute("UPDATE entouramentos SET diagnostico_data=?,resultado=?,observacoes=?,ativo=0 WHERE id=?",
                              (data_diag,resultado,obs_final,eid))
                    c.commit()
                    flash(f"Diagnóstico {resultado.upper()} registrado para a matriz {reg['matriz_brinco']}.","ok")
                    c.close(); return redirect(url_for("iatf"))

        elif acao=="liberar_iatf_matriz":
            b=f.get("matriz_brinco","").strip()
            voltar=(f.get("voltar_modo","") or "touro").strip().lower()
            if b:
                reg=c.execute("""SELECT id,observacoes FROM inseminacoes WHERE matriz_brinco=?
                                 AND LOWER(TRIM(COALESCE(resultado,''))) NOT IN ('vazia','cancelado')
                                 ORDER BY id DESC LIMIT 1""",(b,)).fetchone()
                if reg:
                    obs=(reg["observacoes"] or "").strip()
                    nota="IATF cancelada para troca de método reprodutivo."
                    obs_final=(obs+"\n"+nota).strip() if obs else nota
                    c.execute("UPDATE inseminacoes SET resultado='Cancelado', observacoes=? WHERE id=?",(obs_final,reg["id"]))
                    c.commit(); flash(f"Matriz {b} retirada do IATF e liberada para TOURO.","ok")
                else:
                    flash("Não foi encontrado IATF ativo para esta matriz.","erro")
                c.close(); return redirect(url_for("iatf", modo=voltar if voltar in ('touro','iatf','troca') else 'touro'))

        elif acao=="liberar_touro_matriz":
            b=f.get("matriz_brinco","").strip()
            voltar=(f.get("voltar_modo","") or "iatf").strip().lower()
            if b:
                c.execute("UPDATE entouramentos SET ativo=0 WHERE matriz_brinco=? AND COALESCE(ativo,1)=1",(b,))
                mudou=c.rowcount
                c.commit()
                if mudou:
                    flash(f"Matriz {b} retirada do TOURO e liberada para IATF.","ok")
                else:
                    flash("Não foi encontrado entouramento ativo para esta matriz.","erro")
                c.close(); return redirect(url_for("iatf", modo=voltar if voltar in ('touro','iatf','troca') else 'iatf'))

        elif acao=="cadastrar_protocolo":
            nome=f.get("nome","").strip()
            if not nome:
                flash("Informe o nome do protocolo.","erro")
            else:
                def inteiro(v):
                    try: return int(v) if str(v).strip() else None
                    except: return None
                try:
                    c.execute("""INSERT INTO protocolos_iatf
                                 (nome,etapa_d0,dias_etapa2,etapa2,dias_retirada,retirada,dias_ia,etapa_ia,observacoes)
                                 VALUES(?,?,?,?,?,?,?,?,?)""",
                              (nome,f.get("etapa_d0","").strip(),inteiro(f.get("dias_etapa2")) or 8,
                               f.get("etapa2","").strip(),inteiro(f.get("dias_retirada")) or 8,
                               f.get("retirada","").strip(),inteiro(f.get("dias_ia")) or 10,
                               f.get("etapa_ia","").strip(),f.get("observacoes","").strip()))
                    c.commit(); flash("Protocolo IATF cadastrado.","ok")
                    c.close()
                    return redirect(url_for("iatf"))
                except sqlite3.IntegrityError:
                    flash("Já existe um protocolo com esse nome.","erro")

        elif acao=="excluir_protocolo":
            pid=f.get("protocolo_id","").strip()
            if pid:
                c.execute("UPDATE protocolos_iatf SET ativo=0 WHERE id=?",(pid,))
                c.commit(); flash("Protocolo removido da lista ativa.","ok")

        elif acao=="aplicar_protocolo":
            pid=f.get("protocolo_id","").strip()
            brincos=[b for b in f.getlist("matrizes") if b]
            inicio=f.get("data_inicio") or date.today().isoformat()
            # Observação individual de cada matriz selecionada. Os campos são enviados
            # em duas listas paralelas para não depender do formato do número do brinco.
            obs_brincos=f.getlist("obs_brinco")
            obs_valores=f.getlist("obs_matriz")
            observacoes_por_matriz={
                str(b).strip(): str(o or "").strip()
                for b,o in zip(obs_brincos,obs_valores) if str(b).strip()
            }
            p=c.execute("SELECT * FROM protocolos_iatf WHERE id=? AND ativo=1",(pid,)).fetchone() if pid else None
            if not p:
                flash("Selecione um protocolo cadastrado.","erro")
            elif not brincos:
                flash("Selecione ao menos uma matriz.","erro")
            else:
                # Segurança: só pode iniciar um novo protocolo quem estiver realmente livre.
                # Qualquer IATF ainda ativa (sem resultado VAZIA/CANCELADO) bloqueia nova aplicação,
                # inclusive matrizes em protocolo, aguardando IA ou aguardando diagnóstico.
                permitidos=[]
                bloqueados=[]
                for b in brincos:
                    ult=c.execute("""SELECT resultado FROM inseminacoes
                                     WHERE matriz_brinco=?
                                     ORDER BY id DESC LIMIT 1""",(b,)).fetchone()
                    com_diu=c.execute("""SELECT 1 FROM animais WHERE brinco=? AND COALESCE(diu_aplicado,0)=1 LIMIT 1""",(b,)).fetchone()
                    em_touro=c.execute("SELECT 1 FROM entouramentos WHERE matriz_brinco=? AND COALESCE(ativo,1)=1 LIMIT 1",(b,)).fetchone()
                    resultado_ult=(ult["resultado"] or "").strip().lower() if ult else ""
                    iatf_ativa=bool(ult and resultado_ult not in ("vazia","cancelado"))
                    if com_diu or em_touro or iatf_ativa:
                        bloqueados.append(b)
                    else:
                        permitidos.append(b)

                def somar_dias(data_txt,dias):
                    if not data_txt or dias is None: return ""
                    try:
                        return (datetime.strptime(data_txt,"%Y-%m-%d").date()+timedelta(days=int(dias))).isoformat()
                    except: return ""

                d2=somar_dias(inicio,p["dias_etapa2"])
                dr=somar_dias(inicio,p["dias_retirada"])
                dia=somar_dias(inicio,p["dias_ia"])

                for b in permitidos:
                    obs_protocolo=(p["observacoes"] or "").strip()
                    obs_individual=observacoes_por_matriz.get(str(b),"").strip()
                    partes=[]
                    if obs_protocolo:
                        partes.append(obs_protocolo)
                    if obs_individual:
                        partes.append("Aplicação: "+obs_individual)
                    obs_final="\n".join(partes)
                    c.execute("""INSERT INTO inseminacoes
                                 (matriz_brinco,protocolo,data_inicio,etapa_d0,data_etapa2,etapa2,
                                  data_retirada,retirada,data_ia,etapa_ia,hora_ia,semen_touro,inseminador,
                                  diagnostico_data,resultado,observacoes)
                                 VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                              (b,p["nome"],inicio,p["etapa_d0"] or "",d2,p["etapa2"] or "",
                               dr,p["retirada"] or "",dia,p["etapa_ia"] or "","","","","","",obs_final))

                c.commit()
                if permitidos:
                    flash(f"Protocolo aplicado em {len(permitidos)} matriz(es).","ok")
                if bloqueados:
                    flash("Não aplicado em matriz(es) indisponível(is) por DIU, TOURO ou IATF já ativa: "+", ".join(bloqueados), "erro")
                if permitidos:
                    c.close()
                    return redirect(url_for("iatf"))

        elif acao=="registrar_ia":
            iid=f.get("iatf_id","").strip()
            if not iid:
                flash("Registro de IATF não informado.","erro")
            else:
                atual=c.execute("""SELECT i.observacoes,i.matriz_brinco,COALESCE(a.diu_aplicado,0) AS diu_aplicado
                                  FROM inseminacoes i LEFT JOIN animais a ON a.brinco=i.matriz_brinco
                                  WHERE i.id=?""",(iid,)).fetchone()
                if atual and int(atual["diu_aplicado"] or 0)==1:
                    flash("Matriz com DIU APLICADO não pode participar da Reprodução.","erro")
                    c.close(); return redirect(url_for("iatf"))
                anterior=(atual["observacoes"] or "").strip() if atual else ""
                obs=f.get("observacao_ia","").strip()
                obs_final=(anterior + ("\n" if anterior and obs else "") + (("IA: "+obs) if obs else "")).strip()
                gnrh_aplicado = 1 if f.get("gnrh_aplicado") == "1" else 0
                semen_informado=f.get("semen_touro","").strip()
                c.execute("""UPDATE inseminacoes
                             SET data_ia=?, hora_ia='', semen_touro=?, inseminador='', gnrh_aplicado=?,
                                 diagnostico_data='', resultado='Aguardando diagnóstico', observacoes=?
                             WHERE id=?""",
                          (f.get("data_ia",""),semen_informado,gnrh_aplicado,obs_final,iid))
                c.commit()

                # V6.1.75 — após inseminar, abrir automaticamente a próxima matriz
                # que ainda aguarda IA, mantendo a ordem crescente de brinco.
                brinco_atual=str(atual["matriz_brinco"] or "").strip() if atual else ""
                pendentes=[str(x["matriz_brinco"] or "").strip() for x in c.execute("""
                    SELECT i.matriz_brinco FROM inseminacoes i
                    WHERE LOWER(TRIM(COALESCE(i.resultado,''))) NOT IN ('aguardando diagnóstico','prenhe','vazia','cancelado')
                      AND i.id=(SELECT MAX(i2.id) FROM inseminacoes i2
                                WHERE i2.matriz_brinco=i.matriz_brinco
                                  AND LOWER(TRIM(COALESCE(i2.resultado,''))) NOT IN ('prenhe','vazia','cancelado'))
                      AND EXISTS(SELECT 1 FROM animais a
                                 WHERE a.brinco=i.matriz_brinco AND a.status='Ativo'
                                   AND COALESCE(a.diu_aplicado,0)=0
                                   AND LOWER(TRIM(COALESCE(a.categoria,''))) IN ('vaca','novilha'))
                    ORDER BY CAST(i.matriz_brinco AS INTEGER), i.matriz_brinco COLLATE NOCASE
                """).fetchall() if str(x["matriz_brinco"] or "").strip()]

                def _chave_brinco(txt):
                    txt=str(txt or "")
                    try: return (0,int(txt),txt)
                    except: return (1,0,txt)
                atual_key=_chave_brinco(brinco_atual)
                posteriores=[b for b in pendentes if _chave_brinco(b)>atual_key]
                proxima=posteriores[0] if posteriores else (pendentes[0] if pendentes else "")
                if proxima:
                    flash(f"IA da matriz {brinco_atual} registrada com sucesso. Próxima matriz {proxima} pronta para inseminação.","ok")
                else:
                    flash(f"IA da matriz {brinco_atual} registrada com sucesso. Não há outra matriz aguardando inseminação.","ok")
                c.close()
                return redirect(url_for("iatf", foco=proxima) if proxima else url_for("iatf"))

        elif acao=="excluir_ia":
            iid=f.get("iatf_id","").strip()
            if not iid:
                flash("Registro de IATF não informado.","erro")
            else:
                reg=c.execute("SELECT matriz_brinco FROM inseminacoes WHERE id=?",(iid,)).fetchone()
                if reg:
                    c.execute("DELETE FROM inseminacoes WHERE id=?",(iid,))
                    c.commit()
                    flash(f"Registro de IA/IATF da matriz {reg['matriz_brinco']} excluído.","ok")
                else:
                    flash("Registro de IA/IATF não encontrado.","erro")

        elif acao=="diagnostico":
            iid=f.get("iatf_id","").strip()
            if iid:
                resultado=f.get("resultado","").strip()
                if resultado not in ("Prenhe","Vazia"):
                    flash("Informe o resultado do diagnóstico: Prenhe ou Vazia.","erro")
                else:
                    atual=c.execute("""SELECT i.observacoes,i.matriz_brinco,COALESCE(a.diu_aplicado,0) AS diu_aplicado
                                      FROM inseminacoes i LEFT JOIN animais a ON a.brinco=i.matriz_brinco
                                      WHERE i.id=?""",(iid,)).fetchone()
                    if atual and int(atual["diu_aplicado"] or 0)==1:
                        flash("Matriz com DIU APLICADO não pode participar da Reprodução.","erro")
                        c.close(); return redirect(url_for("iatf"))
                    anterior=(atual["observacoes"] or "").strip() if atual else ""
                    obs=f.get("observacoes_individual","").strip()
                    obs_final=(anterior + ("\n" if anterior and obs else "") + (("Diagnóstico: "+obs) if obs else "")).strip()
                    gnrh_aplicado = 1 if f.get("gnrh_aplicado") == "1" else 0
                    c.execute("""UPDATE inseminacoes
                                 SET diagnostico_data=?, resultado=?, gnrh_aplicado=?, observacoes=?
                                 WHERE id=?""",
                              (f.get("diagnostico_data",""),resultado,gnrh_aplicado,obs_final,iid))
                    c.commit()
                    if resultado=="Prenhe":
                        flash("Prenhez confirmada. A vaca ficará bloqueada para novo protocolo IATF.","ok")
                    else:
                        flash("Diagnóstico VAZIA registrado. A vaca está liberada para repasse IATF.","ok")
                    c.close()
                    return redirect(url_for("iatf"))

    # V6.1.64 — saneamento da rodada IATF atual informada pelo usuário.
    # Todas as matrizes desta rodada iniciaram em 28/08/2026, com IA prevista em 07/09/2026.
    # Se versões anteriores tiverem criado registros ativos duplicados para a mesma matriz
    # com outras datas, eles são preservados como histórico, mas marcados como Cancelado.
    rodada_d0_atual = "2026-08-28"
    rodada_ia_atual = "2026-09-07"
    brincos_rodada = [r["matriz_brinco"] for r in c.execute(
        """SELECT DISTINCT matriz_brinco FROM inseminacoes
           WHERE data_inicio=?
             AND LOWER(TRIM(COALESCE(resultado,''))) <> 'cancelado'""",
        (rodada_d0_atual,)
    ).fetchall()]
    for _brinco in brincos_rodada:
        regs_duplicados = c.execute(
            """SELECT id,observacoes FROM inseminacoes
               WHERE matriz_brinco=?
                 AND data_inicio<>?
                 AND LOWER(TRIM(COALESCE(resultado,''))) NOT IN ('prenhe','vazia','cancelado')""",
            (_brinco, rodada_d0_atual)
        ).fetchall()
        for _reg in regs_duplicados:
            _obs = (_reg["observacoes"] or "").strip()
            _nota = "Registro duplicado retirado da rodada ativa. Rodada válida: D0 28/08/2026 e IA 07/09/2026."
            if _nota not in _obs:
                _obs = (_obs + ("\n" if _obs else "") + _nota).strip()
            c.execute("UPDATE inseminacoes SET resultado='Cancelado', observacoes=? WHERE id=?", (_obs, _reg["id"]))
    if brincos_rodada:
        c.commit()

    protocolos=c.execute("SELECT * FROM protocolos_iatf WHERE ativo=1 ORDER BY nome COLLATE NOCASE").fetchall()
    # Matrizes aptas ao IATF:
    # - todas as VACAS ativas;
    # - NOVILHAS ativas somente quando estiverem no núcleo de 24-36 meses.
    candidatas_iatf=c.execute("""SELECT brinco,nome,lote,categoria,nascimento,COALESCE(diu_aplicado,0) AS diu_aplicado FROM animais
                                  WHERE status='Ativo'
                                    AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha')
                                    AND COALESCE(diu_aplicado,0)=0
                                  ORDER BY CAST(brinco AS INTEGER),brinco""").fetchall()
    todas_vacas=[]
    for a in candidatas_iatf:
        cat=(a["categoria"] or "").strip().lower()
        if cat=="vaca" or (cat=="novilha" and nucleo_idade(a["nascimento"])=="24-36 meses"):
            todas_vacas.append(a)

    # Situação reprodutiva mais recente de cada matriz apta.
    situacao={}
    for v in todas_vacas:
        ult=c.execute("""SELECT id,data_inicio,data_ia,diagnostico_data,resultado,protocolo
                         FROM inseminacoes WHERE matriz_brinco=?
                         ORDER BY id DESC LIMIT 1""",(v["brinco"],)).fetchone()
        if not ult:
            situacao[v["brinco"]]={
                "status":"SEM PROTOCOLO","classe":"livre","teve_protocolo":False
            }
        else:
            res=(ult["resultado"] or "").strip()
            if res=="Prenhe":
                status="PRENHE"
                classe="prenhe"
            elif res=="Vazia":
                status="VAZIA — LIBERADA PARA REPASSE"
                classe="vazia"
            elif res=="Cancelado":
                status="IATF CANCELADA — LIBERADA"
                classe="cancelado"
            elif ult["data_ia"]:
                status="AGUARDANDO DIAGNÓSTICO"
                classe="aguardando"
            else:
                status="PROTOCOLO OK"
                classe="protocolo"
            situacao[v["brinco"]]={
                "status":status,"classe":classe,"teve_protocolo":True,
                "resultado":res,"data_ia":ult["data_ia"] or "",
                "protocolo":ult["protocolo"] or ""
            }

    # Evita duplicidade entre os métodos reprodutivos.
    # IATF permanece ativa até diagnóstico VAZIA; entouramento permanece ativo enquanto o registro existir.
    iatf_bloqueadas_touro=set()
    for v in todas_vacas:
        st=situacao.get(v["brinco"], {})
        if st.get("teve_protocolo") and st.get("classe") not in ("vazia","cancelado"):
            iatf_bloqueadas_touro.add(str(v["brinco"]))
    touro_bloqueadas_iatf={str(r["matriz_brinco"]) for r in c.execute("SELECT DISTINCT matriz_brinco FROM entouramentos WHERE COALESCE(ativo,1)=1").fetchall()}

    # A tela APLICAR PROTOCOLO mostra somente matrizes livres para INICIAR uma nova IATF.
    # Matrizes com protocolo ativo, aguardando IA, aguardando diagnóstico ou prenhes ficam fora.
    # VAZIA/CANCELADO voltam a ficar disponíveis para um novo ciclo.
    vacas=[v for v in todas_vacas if situacao[v["brinco"]]["classe"] in ("livre","vazia","cancelado")]

    # V6.1.29 — opção TOURO na aba Reprodução: somente vacas ativas, em ordem crescente.
    vacas_touro=c.execute("""SELECT brinco,nome,lote,categoria,nascimento,COALESCE(diu_aplicado,0) AS diu_aplicado FROM animais
                            WHERE status='Ativo'
                              AND LOWER(TRIM(COALESCE(categoria,'')))='vaca'
                              AND COALESCE(diu_aplicado,0)=0
                            ORDER BY CAST(brinco AS INTEGER), brinco COLLATE NOCASE""").fetchall()
    # V6.1.46: na seleção do TOURO aparecem SOMENTE matrizes realmente disponíveis.
    # Quem já está no TOURO não volta a aparecer no checklist; quem está em IATF também fica fora.
    vacas_touro_disponiveis=[v for v in vacas_touro
                             if str(v["brinco"]) not in iatf_bloqueadas_touro
                             and str(v["brinco"]) not in touro_bloqueadas_iatf]
    matrizes_iatf_ativas=[v for v in vacas_touro if str(v["brinco"]) in iatf_bloqueadas_touro]
    matrizes_touro_ativas=[v for v in vacas_touro if str(v["brinco"]) in touro_bloqueadas_iatf]
    # Uma matriz aparece uma única vez em "Vacas no Touro", mesmo que versões antigas
    # tenham deixado mais de um registro ativo para o mesmo brinco.
    entouramentos=c.execute("""SELECT e.* FROM entouramentos e
                              WHERE COALESCE(e.ativo,1)=1
                                AND EXISTS (SELECT 1 FROM animais a WHERE a.brinco=e.matriz_brinco AND COALESCE(a.diu_aplicado,0)=0)
                                AND e.id=(SELECT MAX(e2.id) FROM entouramentos e2
                                          WHERE e2.matriz_brinco=e.matriz_brinco
                                            AND COALESCE(e2.ativo,1)=1)
                              ORDER BY CAST(e.matriz_brinco AS INTEGER), e.matriz_brinco COLLATE NOCASE
                              LIMIT 250""").fetchall()

    # V6.1.24 — Etapa 3 (Registrar IA): exibir as matrizes em ordem crescente de brinco
    # e informar o total de matrizes distintas com IATF na listagem.
    rows=c.execute("""SELECT i.* FROM inseminacoes i
                     WHERE LOWER(TRIM(COALESCE(i.resultado,''))) <> 'cancelado'
                       AND EXISTS (SELECT 1 FROM animais a
                                   WHERE a.brinco=i.matriz_brinco
                                     AND a.status='Ativo'
                                     AND COALESCE(a.diu_aplicado,0)=0
                                     AND LOWER(TRIM(COALESCE(a.categoria,''))) IN ('vaca','novilha'))
                       AND i.id=(SELECT MAX(i2.id) FROM inseminacoes i2
                                WHERE i2.matriz_brinco=i.matriz_brinco
                                  AND LOWER(TRIM(COALESCE(i2.resultado,''))) <> 'cancelado')
                     ORDER BY CAST(i.matriz_brinco AS INTEGER), i.matriz_brinco COLLATE NOCASE
                     LIMIT 250""").fetchall()
    total_matrizes_iatf=len({str(r["matriz_brinco"] or "").strip() for r in rows if str(r["matriz_brinco"] or "").strip()})
    # V6.1.69 — a primeira lista de Reprodução mostra TODAS as matrizes
    # elegíveis por categoria/idade e SEM DIU, sem esconder a matriz por
    # histórico anterior de IATF ou TOURO. Assim a escolha do método começa
    # sempre pela própria linha da matriz, como definido no fluxo simplificado.
    candidatas_unificadas=[]
    for a in c.execute("""SELECT brinco,nome,lote,categoria,nascimento,COALESCE(diu_aplicado,0) AS diu_aplicado
                           FROM animais a WHERE status='Ativo'
                             AND LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha')
                             AND COALESCE(diu_aplicado,0)=0
                             AND a.id=(SELECT MAX(am.id) FROM animais am WHERE am.brinco=a.brinco AND am.status='Ativo'
                                       AND LOWER(TRIM(COALESCE(am.categoria,''))) IN ('vaca','novilha'))
                           ORDER BY CAST(brinco AS INTEGER),brinco COLLATE NOCASE""").fetchall():
        cat=(a["categoria"] or "").strip().lower()
        if cat=="novilha" and nucleo_idade(a["nascimento"])!="24-36 meses":
            continue
        candidatas_unificadas.append(a)

    # Processos ativos: uma única linha por matriz, sempre o registro ativo mais recente.
    processos_repro=[]
    ativos_i=c.execute("""SELECT i.* FROM inseminacoes i
                          WHERE LOWER(TRIM(COALESCE(i.resultado,''))) NOT IN ('prenhe','vazia','cancelado')
                            AND i.id=(SELECT MAX(i2.id) FROM inseminacoes i2 WHERE i2.matriz_brinco=i.matriz_brinco
                                      AND LOWER(TRIM(COALESCE(i2.resultado,''))) NOT IN ('prenhe','vazia','cancelado'))
                            AND EXISTS(SELECT 1 FROM animais a WHERE a.brinco=i.matriz_brinco AND a.status='Ativo' AND COALESCE(a.diu_aplicado,0)=0
                                       AND LOWER(TRIM(COALESCE(a.categoria,''))) IN ('vaca','novilha'))""").fetchall()
    for r in ativos_i:
        res=(r["resultado"] or "").strip().lower()
        fase="AGUARDANDO DIAGNÓSTICO" if res=="aguardando diagnóstico" else "AGUARDANDO INSEMINAÇÃO"
        processos_repro.append({"tipo":"IATF","brinco":r["matriz_brinco"],"fase":fase,
                                "data":r["data_inicio"] or "","id":r["id"],
                                "data_ia":r["data_ia"] or "","protocolo":r["protocolo"] or "",
                                "semen_touro":r["semen_touro"] or "",
                                "gnrh_aplicado":int(r["gnrh_aplicado"] or 0)})
    ativos_t=c.execute("""SELECT e.* FROM entouramentos e WHERE COALESCE(e.ativo,1)=1
                           AND e.id=(SELECT MAX(e2.id) FROM entouramentos e2 WHERE e2.matriz_brinco=e.matriz_brinco AND COALESCE(e2.ativo,1)=1)
                           AND EXISTS(SELECT 1 FROM animais a WHERE a.brinco=e.matriz_brinco AND a.status='Ativo' AND COALESCE(a.diu_aplicado,0)=0
                                      AND LOWER(TRIM(COALESCE(a.categoria,''))) IN ('vaca','novilha'))""").fetchall()
    for r in ativos_t:
        processos_repro.append({"tipo":"TOURO","brinco":r["matriz_brinco"],
                                "fase":"COM TOURO — AGUARDANDO DIAGNÓSTICO",
                                "data":r["data_entouramento"] or "","id":r["id"],"data_ia":"",
                                "protocolo":"","semen_touro":"","gnrh_aplicado":0})
    def _ord_repro(x):
        b=str(x.get("brinco") or "")
        try: return (0,int(b),b)
        except: return (1,0,b)
    processos_repro.sort(key=_ord_repro)

    # V6.1.71 — uma única listagem para toda a Reprodução, com troca de método na edição.
    # As matrizes já em IATF/TOURO permanecem na primeira tabela, com seleção
    # e método já marcados e a próxima ação acessível pelo botão EDITAR.
    processos_por_brinco={str(r.get("brinco") or ""): r for r in processos_repro}
    matrizes_repro=[]
    for a in candidatas_unificadas:
        item=dict(a)
        br=str(a["brinco"] or "")
        item["processo"]=processos_por_brinco.get(br)
        item["resultado_repro"]=None
        if not item["processo"]:
            ult_i=c.execute("""SELECT resultado,diagnostico_data FROM inseminacoes
                               WHERE matriz_brinco=? AND LOWER(TRIM(COALESCE(resultado,''))) IN ('prenhe','vazia')
                               ORDER BY COALESCE(diagnostico_data,'') DESC,id DESC LIMIT 1""",(br,)).fetchone()
            ult_t=c.execute("""SELECT resultado,diagnostico_data FROM entouramentos
                               WHERE matriz_brinco=? AND LOWER(TRIM(COALESCE(resultado,''))) IN ('prenhe','vazia')
                               ORDER BY COALESCE(diagnostico_data,'') DESC,id DESC LIMIT 1""",(br,)).fetchone()
            candidatos=[]
            if ult_i: candidatos.append({"resultado":ult_i["resultado"],"data":ult_i["diagnostico_data"] or "","tipo":"IATF"})
            if ult_t: candidatos.append({"resultado":ult_t["resultado"],"data":ult_t["diagnostico_data"] or "","tipo":"TOURO"})
            if candidatos:
                item["resultado_repro"]=sorted(candidatos,key=lambda x:x["data"],reverse=True)[0]
        matrizes_repro.append(item)

    # V6.1.75 — lembra o último SÊMEN / TOURO usado para preencher a próxima IA.
    _ult_semen=c.execute("""SELECT semen_touro FROM inseminacoes
                            WHERE TRIM(COALESCE(semen_touro,''))<>''
                            ORDER BY id DESC LIMIT 1""").fetchone()
    ultimo_semen_touro=(_ult_semen["semen_touro"] or "").strip() if _ult_semen else ""
    foco_repro=(request.args.get("foco", "") or "").strip()

    modo_reproducao=(request.args.get("modo", "") or "").strip().lower()
    contexto=dict(protocolos=protocolos,vacas=vacas,rows=rows,situacao=situacao,
                  total_matrizes_iatf=total_matrizes_iatf, vacas_touro=vacas_touro,
                  vacas_touro_disponiveis=vacas_touro_disponiveis,
                  matrizes_iatf_ativas=matrizes_iatf_ativas, matrizes_touro_ativas=matrizes_touro_ativas,
                  entouramentos=entouramentos, modo_reproducao=modo_reproducao,
                  iatf_bloqueadas_touro=iatf_bloqueadas_touro, touro_bloqueadas_iatf=touro_bloqueadas_iatf,
                  candidatas_unificadas=candidatas_unificadas, processos_repro=processos_repro, matrizes_repro=matrizes_repro,
                  ultimo_semen_touro=ultimo_semen_touro, foco_repro=foco_repro)
    c.close()
    if modo_reproducao == "touro":
        return render_template("reproducao_touro.html", **contexto)
    if modo_reproducao == "iatf":
        return render_template("iatf.html", **contexto)
    if modo_reproducao == "troca":
        return render_template("reproducao_trocas.html", **contexto)
    return render_template("reproducao.html", **contexto)

@app.route("/movimentacoes", methods=["GET","POST"])
@login_required
def movimentacoes():
    c=db()
    passo=int(request.args.get("passo") or request.form.get("passo") or 1)
    wiz=session.get("mov_wizard",{})

    def carregar_selecionados(ids):
        ids=[int(x) for x in ids if str(x).isdigit()]
        if not ids: return []
        q=",".join("?"*len(ids))
        rows=c.execute(f"SELECT * FROM animais WHERE id IN ({q})", ids).fetchall()
        ordem={int(v):i for i,v in enumerate(ids)}
        return sorted(rows,key=lambda r:ordem.get(int(r['id']),999999))

    if request.method=="POST":
        acao=request.form.get("acao","")
        if acao=="limpar":
            session.pop("mov_wizard",None); c.close(); return redirect(url_for("movimentacoes"))
        if acao=="voltar":
            passo=max(1,passo-1)
            c.close(); return redirect(url_for("movimentacoes",passo=passo))

        if passo==1 and acao=="avancar":
            selecionados=[]
            for valor in request.form.getlist("selecionado"):
                try: aid=int(valor)
                except (TypeError,ValueError): continue
                if aid not in selecionados and c.execute("SELECT 1 FROM animais WHERE id=? AND status='Ativo'",(aid,)).fetchone():
                    selecionados.append(aid)
            if not selecionados:
                flash("Selecione ao menos um animal.","erro")
            else:
                wiz={"animal_ids":selecionados}
                session["mov_wizard"]=wiz
                c.close(); return redirect(url_for("movimentacoes",passo=2))

        elif passo==2 and acao=="avancar":
            ids=wiz.get("animal_ids",[])
            if not ids:
                flash("A seleção expirou. Selecione os animais novamente.","erro"); c.close(); return redirect(url_for("movimentacoes"))
            pesos={}
            for aid in ids:
                try: pesos[str(aid)]=float(request.form.get(f"peso_id_{aid}") or 0)
                except ValueError: pesos[str(aid)]=0
            wiz["pesos"]=pesos; session["mov_wizard"]=wiz
            c.close(); return redirect(url_for("movimentacoes",passo=3))

        elif passo==3 and acao=="avancar":
            f=request.form
            forma=f.get("forma_calculo","kg")
            try: valor_ref=float(f.get("valor_kg") or 0) if forma=="kg" else float(f.get("valor_unitario") or 0)
            except ValueError: valor_ref=0
            wiz["valores"]={
                "tipo":f.get("tipo","Venda"), "data":f.get("data") or date.today().isoformat(),
                "banco":f.get("banco",""), "agencia":f.get("agencia",""), "conta_corrente":f.get("conta_corrente",""),
                "cpf_titular":f.get("cpf_titular",""),
                "forma_calculo":forma, "valor_referencia":valor_ref, "observacoes":f.get("observacoes","")
            }
            session["mov_wizard"]=wiz
            c.close(); return redirect(url_for("movimentacoes",passo=4))

        elif passo==4 and acao=="avancar":
            f=request.form
            comprador={
                "nome":f.get("comprador_nome","").strip(), "nome_fantasia":f.get("comprador_nome_fantasia","").strip(),
                "cnpj":f.get("comprador_cnpj","").strip(), "cep":f.get("comprador_cep","").strip(),
                "cidade":f.get("comprador_cidade","").strip(), "endereco":f.get("comprador_endereco","").strip(),
                "observacoes":f.get("comprador_observacoes","").strip()
            }
            if wiz.get("valores",{}).get("tipo","Venda")=="Venda" and not comprador["nome"]:
                flash("Informe o nome do comprador.","erro")
            else:
                wiz["comprador"]=comprador; session["mov_wizard"]=wiz
                c.close(); return redirect(url_for("movimentacoes",passo=5))

        elif passo==5 and acao=="finalizar":
            ids=wiz.get("animal_ids",[]); pesos=wiz.get("pesos",{}); valcfg=wiz.get("valores",{}); comprador=wiz.get("comprador",{})
            if not ids or not valcfg:
                flash("A movimentação expirou. Inicie novamente.","erro"); c.close(); return redirect(url_for("movimentacoes"))
            animais_sel=carregar_selecionados(ids)
            forma=valcfg.get("forma_calculo","kg"); valor_ref=float(valcfg.get("valor_referencia") or 0)
            total_peso=sum(float(pesos.get(str(a['id'])) or 0) for a in animais_sel)
            itens=[]
            for a in animais_sel:
                p=float(pesos.get(str(a['id'])) or 0)
                valor=round(p*valor_ref,2) if forma=="kg" else round(valor_ref,2)
                itens.append((a,p,valor))
            bruto=round(sum(i[2] for i in itens),2); fundo=round(bruto*0.015,2); liquido=round(bruto-fundo,2)
            comprador_id=None
            if comprador.get("nome"):
                c.execute("""INSERT INTO compradores(nome,nome_fantasia,cnpj,cep,cidade,endereco,observacoes) VALUES(?,?,?,?,?,?,?)""",
                          (comprador.get("nome"),comprador.get("nome_fantasia"),comprador.get("cnpj"),comprador.get("cep"),comprador.get("cidade"),comprador.get("endereco"),comprador.get("observacoes")))
                comprador_id=c.execute("SELECT last_insert_rowid()").fetchone()[0]
            codigo='VEN-'+datetime.now().strftime('%Y%m%d%H%M%S')
            c.execute("""INSERT INTO vendas(codigo,data,banco,agencia,conta_corrente,cpf_titular,forma_calculo,valor_referencia,total_peso,total_bruto,percentual_fundo,fundo_rural,total_liquido,observacoes,comprador_id,comprador_nome,comprador_nome_fantasia,comprador_cnpj,comprador_cep,comprador_cidade,comprador_endereco,comprador_observacoes)
                         VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                      (codigo,valcfg.get("data"),valcfg.get("banco",""),valcfg.get("agencia",""),valcfg.get("conta_corrente",""),valcfg.get("cpf_titular",""),forma,valor_ref,total_peso,bruto,1.5,fundo,liquido,valcfg.get("observacoes",""),comprador_id,comprador.get("nome",""),comprador.get("nome_fantasia",""),comprador.get("cnpj",""),comprador.get("cep",""),comprador.get("cidade",""),comprador.get("endereco",""),comprador.get("observacoes","")))
            venda_id=c.execute("SELECT last_insert_rowid()").fetchone()[0]
            tipo=valcfg.get("tipo","Venda")
            for a,p,valor in itens:
                c.execute("INSERT INTO venda_itens(venda_id,brinco,nome,categoria,avulso,peso,valor_individual) VALUES(?,?,?,?,?,?,?)",(venda_id,a['brinco'],a['nome'] or '',a['categoria'] or '',0,p,valor))
                fr=round(valor*0.015,2); liq=round(valor-fr,2)
                c.execute("""INSERT INTO movimentacoes(brinco,data,tipo,valor,destino_origem,peso,observacoes,valor_kg,fundo_rural,frigorifico,valor_bruto,valor_liquido,banco,agencia,conta_corrente)
                             VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                          (a['brinco'],valcfg.get("data"),tipo,valor,comprador.get("nome",""),p,valcfg.get("observacoes",""),valor_ref if forma=="kg" else 0,fr,comprador.get("nome_fantasia") or comprador.get("nome",""),valor,liq,valcfg.get("banco",""),valcfg.get("agencia",""),valcfg.get("conta_corrente","")))
                if tipo in ("Venda","Morte","Transferência"):
                    c.execute("DELETE FROM animais WHERE id=?",(a['id'],))
            c.commit(); session.pop("mov_wizard",None); c.close()
            return redirect(url_for("relatorio_venda",venda_id=venda_id))

    # Dados para exibição
    animais=c.execute("SELECT * FROM animais WHERE status='Ativo' ORDER BY CAST(brinco AS INTEGER),brinco,id").fetchall()
    nucleos_ordem=["0-12 meses","12-24 meses","24-36 meses","+36 meses"]
    animais_por_nucleo={n:[] for n in nucleos_ordem}; animais_sem_nucleo=[]
    for a in animais:
        n=nucleo_idade(a['nascimento'])
        (animais_por_nucleo[n] if n in animais_por_nucleo else animais_sem_nucleo).append(a)
    selecionados_rows=carregar_selecionados(wiz.get("animal_ids",[]))
    selected_nucleo = nucleo_idade(selecionados_rows[0]['nascimento']) if selecionados_rows else ""
    vendas_realizadas=c.execute("""
        SELECT v.*, COUNT(vi.id) AS quantidade_animais
        FROM vendas v
        LEFT JOIN venda_itens vi ON vi.venda_id=v.id
        GROUP BY v.id
        ORDER BY COALESCE(v.data,'') DESC, v.id DESC
    """).fetchall()
    c.close()
    return render_template("movimentacoes.html",animais_por_nucleo=animais_por_nucleo,nucleos_ordem=nucleos_ordem,animais_sem_nucleo=animais_sem_nucleo,passo=passo,wiz=wiz,selecionados_rows=selecionados_rows,selected_nucleo=selected_nucleo,vendas_realizadas=vendas_realizadas)



def _pdf_escape_text(text):
    raw = str(text or "").encode("cp1252", "replace")
    return raw.replace(b"\\", b"\\\\").replace(b"(", b"\\(").replace(b")", b"\\)")

def _pdf_money(value):
    try:
        return ("R$ %.2f" % float(value or 0)).replace(".", ",")
    except Exception:
        return "R$ 0,00"

def _pdf_num(value, casas=1):
    try:
        return (("%." + str(casas) + "f") % float(value or 0)).replace(".", ",")
    except Exception:
        return "0,0" if casas == 1 else "0,00"

def _jpeg_size(path):
    # Leitura mínima das dimensões de JPEG, sem dependências externas.
    data = Path(path).read_bytes()
    i = 2
    while i < len(data) - 9:
        if data[i] != 0xFF:
            i += 1; continue
        marker = data[i+1]; i += 2
        if marker in (0xD8, 0xD9):
            continue
        if i + 2 > len(data): break
        seglen = int.from_bytes(data[i:i+2], "big")
        if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
            h = int.from_bytes(data[i+3:i+5], "big")
            w = int.from_bytes(data[i+5:i+7], "big")
            return w, h
        i += seglen
    return 1, 1

def gerar_pdf_venda(venda, itens):
    """Gera PDF A4 do relatório de venda usando somente a biblioteca padrão.
    Funciona offline e não depende do navegador nem de pacotes adicionais.
    """
    from io import BytesIO

    W, H = 595.28, 841.89  # A4 em pontos
    M = 36
    green = (0.04, 0.34, 0.18)
    light = (0.93, 0.96, 0.94)
    border = (0.72, 0.79, 0.74)

    objects = []
    def add_obj(content=b""):
        objects.append(content if isinstance(content, bytes) else content.encode("latin1"))
        return len(objects)
    def set_obj(obj_id, content):
        objects[obj_id-1] = content if isinstance(content, bytes) else content.encode("latin1")

    f1 = add_obj(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
    f2 = add_obj(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>")

    image_ids = {}
    for key, rel in (("Logo", "static/logo-paineira-pdf.jpg"), ("Flag", "static/bandeira-rs-pdf.jpg")):
        path = Path(__file__).resolve().parent / rel
        if path.exists():
            data = path.read_bytes(); iw, ih = _jpeg_size(path)
            hdr = f"<< /Type /XObject /Subtype /Image /Width {iw} /Height {ih} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length {len(data)} >>\nstream\n".encode("ascii")
            image_ids[key] = add_obj(hdr + data + b"\nendstream")

    pages_id = add_obj()
    page_records = []
    cmds = []
    y = H - 34

    def rgb(c, stroke=False):
        op = "RG" if stroke else "rg"
        return f"{c[0]:.3f} {c[1]:.3f} {c[2]:.3f} {op}"
    def text(x, yy, value, size=9, bold=False, color=(0,0,0), align=None):
        raw = _pdf_escape_text(value)
        # largura aproximada para centralização/direita; suficiente para cabeçalhos.
        approx = len(str(value or "")) * size * 0.52
        if align == "center": x -= approx/2
        elif align == "right": x -= approx
        font = "F2" if bold else "F1"
        cmds.append(rgb(color).encode("ascii") + b"\n")
        cmds.append(f"BT /{font} {size:.1f} Tf 1 0 0 1 {x:.2f} {yy:.2f} Tm (".encode("ascii") + raw + b") Tj ET\n")
    def line(x1,y1,x2,y2,width=1,color=green):
        cmds.append((rgb(color,True)+f"\n{width:.2f} w {x1:.2f} {y1:.2f} m {x2:.2f} {y2:.2f} l S\n").encode("ascii"))
    def rect(x,yy,w,h,fill=None,stroke=border,r=0):
        if fill is not None:
            cmds.append((rgb(fill)+"\n").encode("ascii"))
        if stroke is not None:
            cmds.append((rgb(stroke,True)+"\n").encode("ascii"))
        op = "B" if fill is not None and stroke is not None else ("f" if fill is not None else "S")
        cmds.append(f"{x:.2f} {yy:.2f} {w:.2f} {h:.2f} re {op}\n".encode("ascii"))
    def image(name,x,yy,w,h):
        if name in image_ids:
            cmds.append(f"q {w:.2f} 0 0 {h:.2f} {x:.2f} {yy:.2f} cm /{name} Do Q\n".encode("ascii"))
    def wrap(value, max_chars):
        words=str(value or "-").split(); lines=[]; cur=""
        for word in words:
            candidate=(cur+" "+word).strip()
            if len(candidate)<=max_chars: cur=candidate
            else:
                if cur: lines.append(cur)
                cur=word
        if cur: lines.append(cur)
        return lines or ["-"]

    def header(first=False):
        nonlocal y
        image("Logo", M, H-104, 58, 58)
        image("Flag", W-M-42, H-102, 42, 52)
        text(W/2, H-56, "AGROPECUÁRIA PAINEIRA", 17, True, green, "center")
        text(W/2, H-72, "Restinga Sêca - Vila Santuário - CEP 97200-000", 8, False, (0.28,0.36,0.31), "center")
        text(W/2, H-90, "RELATÓRIO DA VENDA", 12, True, green, "center")
        text(W/2, H-105, f"Código: {venda['codigo']}   Data: {_br_date(venda['data'])}", 8.5, False, (0,0,0), "center")
        line(M,H-115,W-M,H-115,1.5,green)
        y=H-132
    def finish_page():
        nonlocal cmds
        content=b"".join(cmds)
        content_id=add_obj(f"<< /Length {len(content)} >>\nstream\n".encode("ascii")+content+b"endstream")
        resources=f"<< /Font << /F1 {f1} 0 R /F2 {f2} 0 R >>"
        if image_ids:
            resources += " /XObject << " + " ".join(f"/{k} {v} 0 R" for k,v in image_ids.items()) + " >>"
        resources += " >>"
        page_id=add_obj(f"<< /Type /Page /Parent {pages_id} 0 R /MediaBox [0 0 {W:.2f} {H:.2f}] /Resources {resources} /Contents {content_id} 0 R >>")
        page_records.append(page_id); cmds=[]
    def need(height):
        nonlocal y
        if y-height < 45:
            finish_page(); header()
    def section_title(title):
        nonlocal y
        need(30)
        rect(M,y-20,W-2*M,22,fill=light,stroke=border)
        text(M+8,y-14,title,10,True,green)
        y-=30
    def field_lines(label, value, max_chars=88):
        nonlocal y
        lines=wrap(value,max_chars)
        need(14*len(lines)+3)
        for idx,ln in enumerate(lines):
            if idx==0:
                text(M+8,y,f"{label}: ",8.5,True,(0.05,0.18,0.10))
                # usa posição aproximada após o rótulo
                text(M+8+len(label)*4.8+10,y,ln,8.5,False,(0,0,0))
            else: text(M+8,y,ln,8.5,False,(0,0,0))
            y-=12

    header(True)
    section_title("DADOS DO VENDEDOR")
    cpf_vendedor = venda['cpf_titular'] or '-'
    nomes_vendedores = {
        "976.068.470-53": "MARCIO GRIGOLETTO ESPINDOLA",
        "801.910.530-15": "MARIA CAROLINA GRIGOLETTO ESPINDOLA",
    }
    field_lines("Nome", nomes_vendedores.get(cpf_vendedor, '-'))
    field_lines("CPF", cpf_vendedor)
    field_lines("Banco / Agência / Conta", f"{venda['banco'] or '-'}   /   {venda['agencia'] or '-'}   /   {venda['conta_corrente'] or '-'}")
    y-=4

    section_title("DADOS DO COMPRADOR")
    field_lines("Nome", venda['comprador_nome'] or '-')
    field_lines("Nome fantasia", venda['comprador_nome_fantasia'] or '-')
    field_lines("CNPJ", venda['comprador_cnpj'] or '-')
    field_lines("CEP / Cidade", f"{venda['comprador_cep'] or '-'}   {venda['comprador_cidade'] or '-'}")
    field_lines("Endereço", venda['comprador_endereco'] or '-')
    if venda['comprador_observacoes']:
        field_lines("Observação", venda['comprador_observacoes'])
    y-=4

    section_title("DADOS DO ANIMAL")
    col=[M, M+90, M+250, M+365, W-M]
    rowh=18
    need(rowh*2)
    rect(M,y-rowh,W-2*M,rowh,fill=green,stroke=green)
    headers=["Brinco","Categoria","Peso (kg)","Valor"]
    for j,hv in enumerate(headers): text(col[j]+4,y-12,hv,7.5,True,(1,1,1))
    y-=rowh
    for i in itens:
        need(rowh)
        rect(M,y-rowh,W-2*M,rowh,fill=None,stroke=border)
        vals=[i['brinco'],i['categoria'] or '',_pdf_num(i['peso'],1),_pdf_money(i['valor_individual'])]
        for j,v in enumerate(vals):
            s=str(v)
            maxlen=[14,24,14,20][j]
            if len(s)>maxlen: s=s[:maxlen-1]+"…"
            text(col[j]+4,y-12,s,7.5,False,(0,0,0))
        y-=rowh
    y-=8

    section_title("VALORES DA VENDA")
    vals=[
        ("Peso total", f"{_pdf_num(venda['total_peso'],1)} kg"),
        ("Valor bruto", _pdf_money(venda['total_bruto'])),
        ("Fundo Rural (1,5%)", _pdf_money(venda['fundo_rural'])),
        ("Valor líquido", _pdf_money(venda['total_liquido'])),
    ]
    for idx,(lab,val) in enumerate(vals):
        need(20)
        x=M+8 if idx%2==0 else M+270
        if idx%2==0 and idx+1<len(vals):
            pass
        text(x,y,lab,8.5,False,(0.18,0.28,0.21)); text(x+105,y,val,9,True,green)
        if idx%2==1 or idx==len(vals)-1: y-=18
    y-=2
    if venda['observacoes']:
        field_lines("Observações da venda", venda['observacoes'])

    finish_page()
    set_obj(pages_id, f"<< /Type /Pages /Kids [{' '.join(str(x)+' 0 R' for x in page_records)}] /Count {len(page_records)} >>")
    catalog_id=add_obj(f"<< /Type /Catalog /Pages {pages_id} 0 R >>")

    out=BytesIO(); out.write(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets=[0]
    for idx,obj in enumerate(objects,1):
        offsets.append(out.tell()); out.write(f"{idx} 0 obj\n".encode("ascii")); out.write(obj); out.write(b"\nendobj\n")
    xref=out.tell(); out.write(f"xref\n0 {len(objects)+1}\n".encode("ascii")); out.write(b"0000000000 65535 f \n")
    for off in offsets[1:]: out.write(f"{off:010d} 00000 n \n".encode("ascii"))
    out.write(f"trailer\n<< /Size {len(objects)+1} /Root {catalog_id} 0 R >>\nstartxref\n{xref}\n%%EOF".encode("ascii"))
    out.seek(0); return out

@app.route("/movimentacoes/venda/<int:venda_id>/excluir", methods=["POST"])
@login_required
def excluir_venda_realizada(venda_id):
    c=db()
    venda=c.execute("SELECT id FROM vendas WHERE id=?",(venda_id,)).fetchone()
    if not venda:
        c.close(); abort(404)
    c.execute("DELETE FROM venda_itens WHERE venda_id=?",(venda_id,))
    c.execute("DELETE FROM vendas WHERE id=?",(venda_id,))
    c.commit(); c.close()
    flash("Venda realizada excluída do histórico.","ok")
    return redirect(url_for("movimentacoes",historico=1))

