@app.route("/relatorio/lista/<tipo>")
@login_required
def relatorio_lista(tipo):
    c=db()
    specs={
        'nascimentos': ('Relação de nascimentos', "SELECT terneiro_brinco AS 'Terneiro', vaca_brinco AS 'Vaca/Mãe', sexo AS 'Sexo', data_nascimento AS 'Ano/Data', observacoes AS 'Observações' FROM nascimentos ORDER BY CASE WHEN terneiro_brinco GLOB '[0-9]*' THEN 0 ELSE 1 END, CASE WHEN terneiro_brinco GLOB '[0-9]*' THEN CAST(terneiro_brinco AS INTEGER) ELSE NULL END, terneiro_brinco COLLATE NOCASE, id"),
        'categorias': ('Animais ativos por categoria', "SELECT categoria AS 'Categoria', COUNT(*) AS 'Quantidade' FROM animais WHERE status='Ativo' GROUP BY categoria ORDER BY categoria"),
        'campos': ('Cadastro de campos e lotação', "SELECT c.nome AS 'Campo/Lote', c.area_ha AS 'Área ha', c.pastagem AS 'Pastagem', COUNT(a.id) AS 'Animais' FROM campos c LEFT JOIN animais a ON a.status='Ativo' AND a.lote=c.nome GROUP BY c.id ORDER BY c.nome"),
        'iatf': ('Protocolos de inseminação / IATF', "SELECT matriz_brinco AS 'Matriz', protocolo AS 'Protocolo', data_inicio AS 'Início', data_ia AS 'IA', semen_touro AS 'Sêmen/Touro', resultado AS 'Resultado', observacoes AS 'Observações' FROM inseminacoes ORDER BY id DESC"),
        'pesagens': ('Histórico de pesagens e ganho de peso', "SELECT brinco AS 'Brinco', data AS 'Data', peso AS 'Peso kg', lote AS 'Campo/Lote', observacoes AS 'Observações' FROM pesagens ORDER BY data DESC,id DESC"),
        'medicacoes': ('Medicações e próximos manejos', "SELECT data AS 'Data', brinco AS 'Brinco', lote AS 'Campo/Lote', tipo AS 'Tipo', produto AS 'Produto', dose AS 'Dose', printf('R$ %.2f',COALESCE(custo_animal,0)) AS 'Custo/animal', proxima_data AS 'Próximo manejo' FROM sanidade ORDER BY data DESC,id DESC"),
        'movimentacoes': ('Compras, vendas e movimentações', "SELECT data AS 'Data', brinco AS 'Brinco', tipo AS 'Tipo', peso AS 'Peso', valor_bruto AS 'Valor bruto', fundo_rural AS 'Fundo Rural', valor_liquido AS 'Líquido' FROM movimentacoes ORDER BY data DESC,id DESC")
    }
    if tipo not in specs: c.close(); abort(404)
    titulo,sql=specs[tipo]; rows=c.execute(sql).fetchall()
    resumo_terneiros = None
    if tipo == 'nascimentos':
        cont = c.execute("""
            SELECT COUNT(*) AS total,
                   SUM(CASE WHEN LOWER(TRIM(COALESCE(sexo,''))) IN ('m','macho','masculino') THEN 1 ELSE 0 END) AS machos,
                   SUM(CASE WHEN LOWER(TRIM(COALESCE(sexo,''))) IN ('f','fêmea','femea','feminino') THEN 1 ELSE 0 END) AS femeas
            FROM nascimentos
        """).fetchone()
        resumo_terneiros = {
            'total': int(cont['total'] or 0),
            'machos': int(cont['machos'] or 0),
            'femeas': int(cont['femeas'] or 0)
        }
    c.close()
    colunas=list(rows[0].keys()) if rows else []
    return render_template('relatorio_lista.html',titulo=titulo,rows=rows,colunas=colunas,emissao=datetime.now().strftime('%d/%m/%Y %H:%M'),resumo_terneiros=resumo_terneiros)

@app.route("/relatorio/reproducao")
@login_required
def relatorio_reproducao():
    c=db()
    # O mesmo número de brinco pode existir em uma matriz e em um terneiro.
    # Por isso, o relatório liga o registro reprodutivo a UMA ÚNICA matriz ativa
    # (VACA/NOVILHA), evitando duplicidade causada por JOIN apenas pelo brinco.
    touro=c.execute("""SELECT e.matriz_brinco AS brinco, a.categoria, a.raca,
                              e.data_entouramento AS data_inicio, COALESCE(e.observacoes,'') AS observacoes
                       FROM entouramentos e
                       JOIN animais a ON a.id=(
                           SELECT MAX(am.id) FROM animais am
                           WHERE am.brinco=e.matriz_brinco
                             AND am.status='Ativo'
                             AND COALESCE(am.diu_aplicado,0)=0
                             AND LOWER(TRIM(COALESCE(am.categoria,''))) IN ('vaca','novilha')
                       )
                       WHERE COALESCE(e.ativo,1)=1
                         AND e.id=(SELECT MAX(e2.id) FROM entouramentos e2
                                   WHERE e2.matriz_brinco=e.matriz_brinco AND COALESCE(e2.ativo,1)=1)
                       ORDER BY CASE WHEN e.matriz_brinco GLOB '[0-9]*' THEN CAST(e.matriz_brinco AS INTEGER) ELSE 999999999 END,
                                e.matriz_brinco COLLATE NOCASE""").fetchall()
    iatf=c.execute("""SELECT i.matriz_brinco AS brinco, a.categoria, a.raca, i.protocolo,
                              i.data_inicio, i.data_ia, i.semen_touro, i.diagnostico_data, i.resultado,
                              COALESCE(i.gnrh_aplicado,0) AS gnrh_aplicado, COALESCE(i.observacoes,'') AS observacoes
                       FROM inseminacoes i
                       JOIN animais a ON a.id=(
                           SELECT MAX(am.id) FROM animais am
                           WHERE am.brinco=i.matriz_brinco
                             AND am.status='Ativo'
                             AND COALESCE(am.diu_aplicado,0)=0
                             AND LOWER(TRIM(COALESCE(am.categoria,''))) IN ('vaca','novilha')
                       )
                       WHERE LOWER(TRIM(COALESCE(i.resultado,''))) NOT IN ('prenhe','vazia','cancelado')
                         -- Se a matriz está atualmente com TOURO, esse é o método vigente.
                         -- Registros antigos de IATF não podem fazê-la aparecer também no grupo IATF.
                         AND NOT EXISTS (
                             SELECT 1 FROM entouramentos e_atual
                             WHERE e_atual.matriz_brinco=i.matriz_brinco
                               AND COALESCE(e_atual.ativo,1)=1
                         )
                         AND i.id=(SELECT MAX(i2.id) FROM inseminacoes i2 WHERE i2.matriz_brinco=i.matriz_brinco AND LOWER(TRIM(COALESCE(i2.resultado,''))) <> 'cancelado')
                       ORDER BY CASE WHEN i.matriz_brinco GLOB '[0-9]*' THEN CAST(i.matriz_brinco AS INTEGER) ELSE 999999999 END,
                                i.matriz_brinco COLLATE NOCASE""").fetchall()
    diu=c.execute("""SELECT a.brinco, a.categoria, a.raca, a.nascimento AS ano_safra, a.lote AS campo_lote
                       FROM animais a
                       WHERE a.status='Ativo'
                         AND COALESCE(a.diu_aplicado,0)=1
                         AND LOWER(TRIM(COALESCE(a.categoria,''))) IN ('vaca','novilha')
                         AND a.id=(SELECT MAX(am.id) FROM animais am
                                   WHERE am.brinco=a.brinco AND am.status='Ativo'
                                     AND COALESCE(am.diu_aplicado,0)=1
                                     AND LOWER(TRIM(COALESCE(am.categoria,''))) IN ('vaca','novilha'))
                       ORDER BY CASE WHEN a.brinco GLOB '[0-9]*' THEN CAST(a.brinco AS INTEGER) ELSE 999999999 END,
                                a.brinco COLLATE NOCASE""").fetchall()
    c.close()
    return render_template('relatorio_reproducao.html', touro=touro, iatf=iatf, diu=diu,
                           emissao=datetime.now().strftime('%d/%m/%Y %H:%M'))

@app.route("/relatorio/iatf/<etapa>")
@login_required
def relatorio_iatf_etapa(etapa):
    etapa=(etapa or '').strip().lower()
    if etapa not in ('aplicar','registrar','diagnostico'):
        abort(404)
    c=db()
    # IMPORTANTE: não fazemos JOIN direto com animais por brinco, pois o mesmo número
    # pode existir em uma matriz e em um terneiro. EXISTS evita linhas duplicadas.
    matriz_ativa = """EXISTS (SELECT 1 FROM animais a
                               WHERE a.brinco=i.matriz_brinco
                                 AND a.status='Ativo'
                                 AND COALESCE(a.diu_aplicado,0)=0
                                 AND LOWER(TRIM(COALESCE(a.categoria,''))) IN ('vaca','novilha'))"""
    ultimo_iatf = "i.id=(SELECT MAX(i2.id) FROM inseminacoes i2 WHERE i2.matriz_brinco=i.matriz_brinco AND LOWER(TRIM(COALESCE(i2.resultado,''))) <> 'cancelado')"
    ordem = """ORDER BY CASE WHEN i.matriz_brinco GLOB '[0-9]*' THEN CAST(i.matriz_brinco AS INTEGER) ELSE 999999999 END,
                       i.matriz_brinco COLLATE NOCASE"""

    if etapa in ('aplicar','registrar'):
        # Protocolo aplicado e IA ainda NÃO registrada. data_ia pode conter a data prevista;
        # o preenchimento de semen_touro é o marcador do registro efetivo da IA.
        sql=f"""SELECT i.matriz_brinco AS brinco, i.protocolo, i.data_inicio, i.data_ia,
                       i.semen_touro, COALESCE(i.observacoes,'') AS observacoes
                FROM inseminacoes i
                WHERE {matriz_ativa}
                  AND COALESCE(TRIM(i.resultado),'')=''
                  AND COALESCE(TRIM(i.semen_touro),'')=''
                  AND {ultimo_iatf}
                {ordem}"""
        rows=c.execute(sql).fetchall()
        titulo='IATF — AGUARDANDO INSEMINAÇÃO' if etapa=='aplicar' else 'IATF — PARA REGISTRAR IA'
    else:
        # IA efetivamente registrada e diagnóstico ainda pendente.
        sql=f"""SELECT i.matriz_brinco AS brinco, i.protocolo, i.data_inicio, i.data_ia,
                       i.diagnostico_data, i.resultado, COALESCE(i.observacoes,'') AS observacoes
                FROM inseminacoes i
                WHERE {matriz_ativa}
                  AND COALESCE(TRIM(i.semen_touro),'')<>''
                  AND LOWER(TRIM(COALESCE(i.resultado,''))) NOT IN ('prenhe','vazia','cancelado')
                  AND {ultimo_iatf}
                {ordem}"""
        rows=c.execute(sql).fetchall()
        titulo='IATF — AGUARDANDO DIAGNÓSTICO'
    c.close()
    return render_template('relatorio_iatf_etapa.html', etapa=etapa, titulo=titulo, rows=rows,
                           emissao=datetime.now().strftime('%d/%m/%Y %H:%M'))

@app.route("/relatorio/rebanho")
@login_required
def relatorio_rebanho():
    atualizar_categorias_automaticas()
    c=db()
    dados=c.execute("""SELECT brinco, categoria, raca, nascimento, lote,
                             COALESCE(diu_aplicado,0) AS diu_aplicado,
                             COALESCE(observacoes,'') AS observacoes
                      FROM animais
                      WHERE LOWER(TRIM(COALESCE(categoria,''))) IN ('vaca','novilha')
                      ORDER BY CASE WHEN brinco GLOB '[0-9]*'
                      THEN CAST(brinco AS INTEGER) ELSE 999999999 END,brinco""").fetchall()
    rows=[]
    for a in dados:
        item=dict(a)
        item["nucleo"] = nucleo_idade(a["nascimento"])

        # Situação reprodutiva calculada em tempo real para o relatório de Matrizes.
        # Prioridade: DIU > monta com touro ativa > etapa mais recente da IATF > livre.
        if int(a["diu_aplicado"] or 0) == 1:
            item["situacao_reprodutiva"] = "DIU APLICADO — INAPTA"
            item["situacao_classe"] = "diu"
        else:
            no_touro=c.execute("""SELECT 1 FROM entouramentos
                                  WHERE matriz_brinco=? AND COALESCE(ativo,1)=1
                                  LIMIT 1""",(a["brinco"],)).fetchone()
            if no_touro:
                item["situacao_reprodutiva"] = "MONTA TOURO"
                item["situacao_classe"] = "touro"
            else:
                ult=c.execute("""SELECT data_inicio,data_ia,diagnostico_data,resultado,protocolo
                                 FROM inseminacoes WHERE matriz_brinco=?
                                 ORDER BY id DESC LIMIT 1""",(a["brinco"],)).fetchone()
                if not ult:
                    item["situacao_reprodutiva"] = "LIVRE PARA REPRODUÇÃO"
                    item["situacao_classe"] = "livre"
                else:
                    res=(ult["resultado"] or "").strip().lower()
                    if res == "prenhe":
                        item["situacao_reprodutiva"] = "PRENHE — IATF"
                        item["situacao_classe"] = "prenhe"
                    elif res == "vazia":
                        item["situacao_reprodutiva"] = "VAZIA — LIVRE"
                        item["situacao_classe"] = "livre"
                    elif res == "cancelado":
                        item["situacao_reprodutiva"] = "LIVRE PARA REPRODUÇÃO"
                        item["situacao_classe"] = "livre"
                    elif (ult["data_ia"] or "").strip():
                        item["situacao_reprodutiva"] = "IATF — AGUARDANDO DIAGNÓSTICO"
                        item["situacao_classe"] = "iatf"
                    else:
                        item["situacao_reprodutiva"] = "IATF — PROTOCOLO"
                        item["situacao_classe"] = "iatf"
        rows.append(item)
    c.close()
    return render_template("relatorio_rebanho.html",rows=rows,emissao=datetime.now().strftime("%d/%m/%Y %H:%M"))

@app.route("/backup")
@login_required
def backup():
    c=db(); c.execute("PRAGMA wal_checkpoint(FULL)"); c.close()
    return send_file(DB_PATH, as_attachment=True, download_name=f"paineira_backup_{date.today().isoformat()}.db")

@app.route("/reset-banco", methods=["GET", "POST"])
@login_required
def reset_banco():
    if request.method == "POST":
        if request.form.get("confirmar_reset") != "SIM":
            flash("Reset cancelado. Nenhum dado foi apagado.", "erro")
            return redirect(url_for("reset_banco"))

        # Cria uma cópia de segurança automática antes de zerar o banco.
        # O backup fica fora do banco novo e permite recuperação em caso de engano.
        backup_dir = BASE_DIR / "backups_automaticos"
        backup_dir.mkdir(parents=True, exist_ok=True)
        carimbo = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_path = backup_dir / f"antes_do_reset_{carimbo}.db"

        try:
            if Path(DB_PATH).exists():
                con = sqlite3.connect(DB_PATH)
                try:
                    con.execute("PRAGMA wal_checkpoint(FULL)")
                finally:
                    con.close()
                shutil.copy2(DB_PATH, backup_path)

            # Remove o banco atual e arquivos auxiliares do SQLite.
            for caminho in [Path(DB_PATH), Path(str(DB_PATH) + "-wal"), Path(str(DB_PATH) + "-shm")]:
                if caminho.exists():
                    caminho.unlink()

            # Recria somente a estrutura vazia do sistema.
            init_db()
            flash("Banco de dados zerado com sucesso. O sistema está pronto para novos cadastros.", "ok")
            return redirect(url_for("dashboard"))
        except Exception as exc:
            flash(f"Não foi possível zerar o banco: {exc}", "erro")
            return redirect(url_for("reset_banco"))

    return render_template("reset_banco.html")


@app.route("/importar-banco", methods=["GET","POST"])
@login_required
def importar_banco():
    if request.method=="POST":
        arq=request.files.get("banco")
        if not arq or not arq.filename.lower().endswith(".db"):
            flash("Selecione um arquivo .db válido.","erro")
        else:
            tmp=BASE_DIR/"importacao.db"
            arq.save(tmp)
            try:
                test=sqlite3.connect(tmp)
                test.execute("SELECT name FROM sqlite_master LIMIT 1").fetchone()
                test.close()
                shutil.copy2(tmp,DB_PATH)
                init_db()
                atualizar_categorias_automaticas()
                flash("Banco importado. Os dados antigos foram carregados.","ok")
                return redirect(url_for("dashboard"))
            except Exception:
                flash("O arquivo não parece ser um banco SQLite válido.","erro")
            finally:
                if tmp.exists(): tmp.unlink()
    return render_template("importar.html")


@app.route("/relatorio/nucleos")
@login_required
def relatorio_nucleos():
    c = db()
    try:
        animais = c.execute("""
            SELECT sexo, nascimento, lote, status
            FROM animais
            WHERE status='Ativo'
        """).fetchall()
    finally:
        c.close()

    nucleos = ["0-12 meses", "12-24 meses", "24-36 meses", "+36 meses"]
    # V6.0.72: o relatório de núcleos não usa mais a condição "Pendentes".
    # Todo animal ativo é contado no seu núcleo de idade, tenha ou não Campo/Lote.
    resumo = {n: {"Macho": 0, "Fêmea": 0} for n in nucleos}

    for a in animais:
        n = nucleo_idade(a["nascimento"])
        if n not in resumo:
            continue
        sexo = "Macho" if str(a["sexo"]).lower().startswith("m") else "Fêmea"
        resumo[n][sexo] += 1

    total_animais = sum(resumo[n][s] for n in nucleos for s in ("Macho", "Fêmea"))

    return render_template("relatorio_nucleos.html",
        resumo=resumo, nucleos=nucleos,
        total_animais=total_animais,
        ano_atual=datetime.now().year)

